payload = json.loads('{"scripts/__init__.py":{"content":"\\"\\"\\"Command entry points for MeshVAE workflows.\\"\\"\\"\\n","sha256":"4ba072263171a95586a324774783d20d4abc21b8d8f7bc0d50461362725dc73a"},"scripts/_paths.py":{"content":"\\"\\"\\"Repository paths shared by organized command entry points.\\"\\"\\"\\nfrom pathlib import Path\\n\\nREPO_ROOT = Path(__file__).resolve().parents[1]\\n\\n# Basenames are retained so launchers can resolve an entry point without\\n# depending on the folder of the launcher itself.\\nSCRIPT_PATHS = {\\n    \'benchmark_hba1c_body_size.py\': \'scripts/benchmarks/benchmark_hba1c_body_size.py\',\\n    \'build_scan_geometry_features.py\': \'scripts/preprocessing/build_scan_geometry_features.py\',\\n    \'check_boson_prior.py\': \'scripts/diagnostics/check_boson_prior.py\',\\n    \'collect_diagnostic_results.py\': \'scripts/diagnostics/collect_diagnostic_results.py\',\\n    \'diagnose_mesh_binary.py\': \'scripts/diagnostics/diagnose_mesh_binary.py\',\\n    \'diagnose_mesh_regression.py\': \'scripts/diagnostics/diagnose_mesh_regression.py\',\\n    \'diagnose_mesh_vae.py\': \'scripts/diagnostics/diagnose_mesh_vae.py\',\\n    \'find_metadata_tsv_for_obj_folder.py\': \'scripts/preprocessing/find_metadata_tsv_for_obj_folder.py\',\\n    \'inspect_npz_tsv_overlap.py\': \'scripts/preprocessing/inspect_npz_tsv_overlap.py\',\\n    \'inspect_scan_metadata_overlap.py\': \'scripts/preprocessing/inspect_scan_metadata_overlap.py\',\\n    \'linear_regression_hba1c.py\': \'scripts/benchmarks/linear_regression_hba1c.py\',\\n    \'mesh_geom_pipeline.py\': \'meshvae/compat/mesh_geom_pipeline.py\',\\n    \'mesh_vae.py\': \'meshvae/compat/mesh_vae.py\',\\n    \'run_all_15_hba1c_models.py\': \'scripts/benchmarks/run_all_15_hba1c_models.py\',\\n    \'run_all_15_models.py\': \'scripts/benchmarks/run_all_15_models.py\',\\n    \'run_body_measurements.py\': \'scripts/measurements/run_body_measurements.py\',\\n    \'run_body_measurements_pointcloud.py\': \'scripts/measurements/run_body_measurements_pointcloud.py\',\\n    \'run_boson_prior_ablation.py\': \'scripts/benchmarks/run_boson_prior_ablation.py\',\\n    \'run_cardiovascular_target_benchmark.py\': \'scripts/benchmarks/run_cardiovascular_target_benchmark.py\',\\n    \'run_full_meshvae_regression_variants.py\': \'scripts/benchmarks/run_full_meshvae_regression_variants.py\',\\n    \'run_full_meshvae_variants.py\': \'scripts/benchmarks/run_full_meshvae_variants.py\',\\n    \'run_hba1c_model_comparison.py\': \'scripts/benchmarks/run_hba1c_model_comparison.py\',\\n    \'run_model_comparison.py\': \'scripts/benchmarks/run_model_comparison.py\',\\n    \'screen_metadata_predictors.py\': \'scripts/analysis/screen_metadata_predictors.py\',\\n    \'train_body_measurements_expanded.py\': \'scripts/training/train_body_measurements_expanded.py\',\\n    \'train_mesh_vae.py\': \'scripts/training/train_mesh_vae.py\',\\n}\\n\\n\\ndef script_path(name: str) -> Path:\\n    \\"\\"\\"Return the absolute path of a named project entry point.\\"\\"\\"\\n    try:\\n        relative = SCRIPT_PATHS[name]\\n    except KeyError as exc:\\n        raise ValueError(f\\"Unknown project entry point: {name}\\") from exc\\n    return REPO_ROOT / relative\\n\\n\\ndef module_name(name: str) -> str:\\n    \\"\\"\\"Return the import name used by ``python -m`` for an entry point.\\"\\"\\"\\n    return SCRIPT_PATHS[name].removesuffix(\\".py\\").replace(\\"/\\", \\".\\")\\n","sha256":"2beccd540a48793a8b4cf576aee8708bb7fef53ea115eaec4becb975eaf0355d"},"scripts/measurements/__init__.py":{"content":"\\"\\"\\"Measurements command entry points.\\"\\"\\"\\n","sha256":"2d54932115fae07a478e4daf66b21940245fdc134231a2a6deafe2fcc25939a0"},"scripts/preprocessing/__init__.py":{"content":"\\"\\"\\"Preprocessing command entry points.\\"\\"\\"\\n","sha256":"0c13aa3af68b747a7063f66bdd682058df60156dcf9458f46e20cdc87874cd80"},"scripts/measurements/run_body_measurements.py":{"content":"#!/usr/bin/env python3\\n\\"\\"\\"Audit, train, and apply scan-only body-measurement regression baselines.\\"\\"\\"\\nfrom __future__ import annotations\\n\\n# Allow direct execution as well as ``python -m`` from the repository checkout.\\nif __package__ in {None, \\"\\"}:\\n    import sys as _sys\\n    from pathlib import Path as _Path\\n    _sys.path.insert(0, str(_Path(__file__).resolve().parents[2]))\\n\\nfrom scripts._paths import REPO_ROOT, script_path\\n\\n\\nimport argparse\\nfrom datetime import datetime, timezone\\nimport hashlib\\nimport json\\nfrom pathlib import Path\\nimport platform\\n\\nimport joblib\\nimport numpy as np\\nimport pandas as pd\\nimport sklearn\\n\\nfrom body_measurements.data import (\\n    align_training, clean_id, clean_participant_id, load_config, load_features, make_splits, read_metadata,\\n)\\nfrom body_measurements.models import fit_models, predict\\nfrom body_measurements.joins import link_validation_rows, scan_candidate_tables\\nfrom body_measurements.obj_features import build_obj_features\\n\\n\\nTEMPLATE = REPO_ROOT / \\"body_measurements\\" / \\"targets.example.json\\"\\n\\n\\ndef write_json(path: Path, value: dict) -> None:\\n    path.write_text(json.dumps(value, indent=2, allow_nan=False) + \\"\\\\n\\", encoding=\\"utf-8\\")\\n\\n\\ndef prepare_output(path: str) -> Path:\\n    output = Path(path)\\n    if output.exists() and (not output.is_dir() or any(output.iterdir())):\\n        raise ValueError(f\\"Output must be a new or empty directory: {output}\\")\\n    output.mkdir(parents=True, exist_ok=True)\\n    return output\\n\\n\\ndef fingerprint(path: str) -> dict:\\n    source = Path(path)\\n    digest = hashlib.sha256()\\n    with source.open(\\"rb\\") as stream:\\n        for chunk in iter(lambda: stream.read(1024 * 1024), b\\"\\"):\\n            digest.update(chunk)\\n    return {\\"path\\": str(source.resolve()), \\"sha256\\": digest.hexdigest()}\\n\\n\\ndef column_inventory(metadata: pd.DataFrame) -> pd.DataFrame:\\n    rows = []\\n    for column in metadata:\\n        text = metadata[column].astype(\\"string\\").str.strip().str.strip(\'\\\\\\"\').str.strip(\\"\'\\")\\n        numbers = pd.to_numeric(text.str.replace(\\",\\", \\".\\", regex=False), errors=\\"coerce\\")\\n        numbers = numbers[np.isfinite(numbers.fillna(np.nan).to_numpy(dtype=float))].astype(float)\\n        rows.append({\\n            \\"column\\": column,\\n            \\"nonempty_rows\\": int((text.notna() & text.ne(\\"\\")).sum()),\\n            \\"finite_numeric_rows\\": len(numbers),\\n            \\"nonpositive_numeric_rows\\": int((numbers <= 0).sum()),\\n            \\"min\\": numbers.min(), \\"median\\": numbers.median(), \\"max\\": numbers.max(),\\n        })\\n    return pd.DataFrame(rows)\\n\\n\\ndef audit(args: argparse.Namespace) -> None:\\n    metadata = read_metadata(args.metadata)\\n    report = {\\n        \\"metadata_rows\\": len(metadata), \\"metadata_columns\\": list(metadata.columns),\\n    }\\n    ids = None\\n    if args.id_col:\\n        if args.id_col not in metadata:\\n            raise ValueError(f\\"ID column {args.id_col!r} is absent. Columns: {list(metadata)}\\")\\n        ids = metadata[args.id_col].map(clean_id)\\n        report.update({\\n            \\"id_col\\": args.id_col, \\"empty_id_rows\\": int(ids.isna().sum()),\\n            \\"duplicate_id_rows\\": int((ids.notna() & ids.duplicated(keep=False)).sum()),\\n            \\"unique_ids\\": int(ids.nunique()),\\n        })\\n    if args.features:\\n        features, feature_audit = load_features(args.features)\\n        report[\\"features\\"] = feature_audit\\n        if ids is not None:\\n            report[\\"matching_unique_ids\\"] = len(set(features.index) & set(ids.dropna()))\\n        if args.config:\\n            if not args.id_col:\\n                raise ValueError(\\"--config alignment audit needs --id-col; link numbered validation rows to OBJs first\\")\\n            targets = load_config(args.config)\\n            _, _, _, alignment = align_training(\\n                features, metadata, targets, args.id_col, args.participant_col,\\n            )\\n            report[\\"alignment\\"] = alignment\\n    elif args.config:\\n        targets = load_config(args.config)\\n        missing = [target[\\"column\\"] for target in targets if target[\\"column\\"] not in metadata]\\n        if missing:\\n            raise ValueError(f\\"Configured target columns missing from metadata: {missing}\\")\\n        report[\\"configured_targets\\"] = [target[\\"name\\"] for target in targets]\\n    output = prepare_output(args.out_dir)\\n    column_inventory(metadata).to_csv(output / \\"metadata_columns.csv\\", index=False)\\n    write_json(output / \\"audit.json\\", report)\\n    # A template is deliberately unfilled: a similar header is not a confirmed label definition.\\n    (output / \\"targets.template.json\\").write_text(TEMPLATE.read_text(encoding=\\"utf-8\\"), encoding=\\"utf-8\\")\\n    print(f\\"[AUDIT] {len(metadata)} metadata rows, {len(metadata.columns)} columns\\")\\n    if \\"matching_unique_ids\\" in report:\\n        print(f\\"[AUDIT] {report[\'matching_unique_ids\']} unique IDs match valid scan features\\")\\n    print(f\\"[OUT] {output.resolve()}\\")\\n\\n\\ndef inspect_sources(args: argparse.Namespace) -> None:\\n    table = scan_candidate_tables(args.metadata, args.obj_root, args.candidate_root)\\n    output = prepare_output(args.out_dir)\\n    table.to_csv(output / \\"candidate_tables.csv\\", index=False)\\n    print(table[[column for column in (\\"path\\", \\"rows\\", \\"measurement_headers_shared\\",\\n                                       \\"best_obj_column\\", \\"best_obj_matches\\",\\n                                       \\"best_row_column\\", \\"best_row_matches\\", \\"error\\")\\n                 if column in table]].to_string(index=False))\\n    print(f\\"[OUT] {output.resolve()}\\")\\n\\n\\ndef link_labels(args: argparse.Namespace) -> None:\\n    validation = read_metadata(args.metadata)\\n    mapping = read_metadata(args.mapping)\\n    available = None\\n    if args.features:\\n        features, _ = load_features(args.features)\\n        available = set(features.index)\\n    linked, join_audit = link_validation_rows(\\n        validation, mapping, validation_row_col=args.validation_row_col,\\n        map_row_col=args.map_row_col, map_obj_col=args.map_obj_col,\\n        available_scan_ids=available,\\n    )\\n    output = prepare_output(args.out_dir)\\n    linked.to_csv(output / \\"metadata_with_scan_id.csv\\", index=False)\\n    write_json(output / \\"join_audit.json\\", {\\n        **join_audit, \\"validation\\": fingerprint(args.metadata),\\n        \\"mapping\\": fingerprint(args.mapping),\\n        \\"features\\": fingerprint(args.features) if args.features else None,\\n    })\\n    print(f\\"[LINK] {join_audit[\'joined_rows\']} uniquely linked validation rows\\")\\n    print(f\\"[OUT] {output.resolve()}\\")\\n\\n\\ndef build_features(args: argparse.Namespace) -> None:\\n    output = Path(args.out_dir)\\n    if output.exists():\\n        allowed = {\\"scan_geometry_features.partial.csv\\"}\\n        if not output.is_dir() or any(path.name not in allowed for path in output.iterdir()):\\n            raise ValueError(f\\"Build output must be new or contain only its resumable partial CSV: {output}\\")\\n    output.mkdir(parents=True, exist_ok=True)\\n    report = build_obj_features(\\n        args.obj_root, output / \\"scan_geometry_features.npz\\",\\n        workers=args.workers, checkpoint_every=args.checkpoint_every,\\n    )\\n    write_json(output / \\"build_audit.json\\", report)\\n    print(f\\"[OUT] {output.resolve()}\\")\\n\\n\\ndef load_split_file(path: str, groups: pd.Series) -> pd.Series:\\n    \\"\\"\\"Reuse an existing manifest while enforcing person-level separation.\\"\\"\\"\\n    frame = read_metadata(path)\\n    if not {\\"scan_id\\", \\"split\\"}.issubset(frame.columns):\\n        raise ValueError(\\"Split file must have scan_id and split columns.\\")\\n    ids = frame.scan_id.map(clean_id)\\n    if ids.isna().any() or ids.duplicated().any():\\n        raise ValueError(\\"Split file contains empty or duplicate scan IDs.\\")\\n    splits = pd.Series(frame[\\"split\\"].astype(str).str.strip().to_numpy(), index=ids, name=\\"split\\")\\n    if not splits.isin([\\"train\\", \\"validation\\", \\"test\\"]).all():\\n        raise ValueError(\\"Split values must be train, validation, or test.\\")\\n    missing = groups.index.difference(splits.index)\\n    if len(missing):\\n        raise ValueError(f\\"Split file lacks {len(missing)} retained scan IDs.\\")\\n    # Check all manifest rows with person identities, including rows without usable labels.\\n    if \\"participant_id\\" in frame.columns:\\n        people = frame.participant_id.map(clean_participant_id)\\n        if people.isna().any():\\n            raise ValueError(\\"Split file has missing participant IDs.\\")\\n        if pd.DataFrame({\\"person\\": people.to_numpy(), \\"split\\": splits.to_numpy()}).groupby(\\"person\\")[\\"split\\"].nunique().gt(1).any():\\n            raise ValueError(\\"Split file assigns one participant to multiple splits.\\")\\n        saved_groups = pd.Series(people.to_numpy(), index=ids)\\n        if not saved_groups.loc[groups.index].eq(groups).all():\\n            raise ValueError(\\"Split file participant IDs disagree with current metadata.\\")\\n    aligned = splits.loc[groups.index]\\n    if pd.DataFrame({\\"group\\": groups, \\"split\\": aligned}).groupby(\\"group\\")[\\"split\\"].nunique().gt(1).any():\\n        raise ValueError(\\"A participant occurs in more than one split.\\")\\n    if set(aligned) != {\\"train\\", \\"validation\\", \\"test\\"}:\\n        raise ValueError(\\"Retained data must include train, validation, and test rows.\\")\\n    return aligned\\n\\n\\ndef train(args: argparse.Namespace) -> None:\\n    targets = load_config(args.config)\\n    features, feature_audit = load_features(args.features)\\n    metadata = read_metadata(args.metadata)\\n    X, y, groups, alignment = align_training(\\n        features, metadata, targets, args.id_col, args.participant_col,\\n    )\\n    splits = (\\n        load_split_file(args.splits, groups) if args.splits\\n        else make_splits(groups, args.seed, args.test_fraction, args.val_fraction)\\n    )\\n    split_counts = []\\n    for name in (\\"train\\", \\"validation\\", \\"test\\"):\\n        rows = splits.eq(name)\\n        for target in y:\\n            observed = rows & y[target].notna()\\n            split_counts.append({\\n                \\"split\\": name, \\"target\\": target, \\"scan_rows\\": int(rows.sum()),\\n                \\"participants\\": int(groups[rows].nunique()), \\"labels\\": int(observed.sum()),\\n                \\"participants_with_labels\\": int(groups[observed].nunique()),\\n            })\\n    output = prepare_output(args.out_dir)\\n    write_json(output / \\"audit.json\\", {\\"features\\": feature_audit, \\"alignment\\": alignment})\\n    pd.DataFrame({\\"scan_id\\": X.index, \\"participant_id\\": groups.to_numpy(), \\"split\\": splits.to_numpy()}).to_csv(\\n        output / \\"splits.csv\\", index=False,\\n    )\\n    pd.DataFrame(split_counts).to_csv(output / \\"label_coverage.csv\\", index=False)\\n    run = {\\n        \\"created_utc\\": datetime.now(timezone.utc).isoformat(),\\n        \\"features\\": fingerprint(args.features), \\"metadata\\": fingerprint(args.metadata),\\n        \\"config\\": fingerprint(args.config), \\"targets\\": targets,\\n        \\"id_col\\": args.id_col, \\"participant_col\\": args.participant_col,\\n        \\"scan_units\\": args.scan_units, \\"output_units\\": \\"cm\\",\\n        \\"seed\\": args.seed, \\"split_source\\": fingerprint(args.splits) if args.splits else \\"generated\\",\\n        \\"test_fraction\\": args.test_fraction, \\"validation_fraction\\": args.val_fraction,\\n        \\"min_train_labels\\": args.min_train_labels, \\"min_validation_labels\\": args.min_validation_labels,\\n        \\"n_estimators\\": args.n_estimators, \\"n_jobs\\": args.n_jobs,\\n        \\"versions\\": {\\"python\\": platform.python_version(), \\"numpy\\": np.__version__,\\n                     \\"pandas\\": pd.__version__, \\"sklearn\\": sklearn.__version__, \\"joblib\\": joblib.__version__},\\n        \\"feature_source\\": \\"scan_geometry_features_only\\",\\n        \\"status\\": \\"fitting\\",\\n    }\\n    write_json(output / \\"run.json\\", run)\\n    print(f\\"[TRAIN] {len(X)} scan rows, {groups.nunique()} participants, {len(y.columns)} mapped targets\\", flush=True)\\n    try:\\n        bundle, metrics, predictions, selection = fit_models(\\n            X, y, splits, seed=args.seed, min_train_labels=args.min_train_labels,\\n            min_validation_labels=args.min_validation_labels,\\n            n_estimators=args.n_estimators, n_jobs=args.n_jobs,\\n        )\\n    except Exception as exc:\\n        run.update(status=\\"failed\\", error=str(exc))\\n        write_json(output / \\"run.json\\", run)\\n        raise\\n    bundle.update({\\"scan_units\\": args.scan_units, \\"target_config\\": targets, \\"run\\": run})\\n    metrics.to_csv(output / \\"metrics.csv\\", index=False)\\n    predictions.to_csv(output / \\"evaluation_predictions.csv\\", index=False)\\n    selection.to_csv(output / \\"model_selection.csv\\", index=False)\\n    run[\\"status\\"] = \\"complete\\"\\n    joblib.dump(bundle, output / \\"model.joblib\\")\\n    write_json(output / \\"run.json\\", run)\\n    print(selection.to_string(index=False))\\n    print(f\\"[OUT] {output.resolve()}\\")\\n\\n\\ndef predict_new(args: argparse.Namespace) -> None:\\n    # joblib models are Python objects: load only checkpoints you trust.\\n    bundle = joblib.load(args.model)\\n    if bundle.get(\\"format_version\\") != 1:\\n        raise ValueError(\\"Unsupported body-measurement model format.\\")\\n    if args.scan_units != bundle.get(\\"scan_units\\"):\\n        raise ValueError(\\"Scan units differ from training. Regenerate features in the original training units.\\")\\n    X, audit_report = load_features(args.features)\\n    result = predict(bundle, X)\\n    result = result.rename(columns={name: f\\"{name}_cm\\" for name in result.columns})\\n    result.index.name = \\"scan_id\\"\\n    output = prepare_output(args.out_dir)\\n    result.to_csv(output / \\"predictions_cm.csv\\")\\n    write_json(output / \\"prediction_audit.json\\", {\\n        \\"features\\": audit_report, \\"rows_predicted\\": len(result),\\n        \\"model\\": fingerprint(args.model), \\"input\\": fingerprint(args.features),\\n        \\"scan_units\\": args.scan_units, \\"output_units\\": \\"cm\\",\\n    })\\n    print(f\\"[PREDICT] {len(result)} scans, {len(result.columns)} measurements; units: cm\\")\\n    print(f\\"[OUT] {output.resolve()}\\")\\n\\n\\ndef build_parser() -> argparse.ArgumentParser:\\n    parser = argparse.ArgumentParser(description=__doc__)\\n    commands = parser.add_subparsers(dest=\\"command\\", required=True)\\n    a = commands.add_parser(\\"audit\\", help=\\"Inspect metadata columns, IDs, and optional label coverage\\")\\n    i = commands.add_parser(\\"inspect-sources\\", help=\\"Find candidate row/OBJ mapping tables beside the validation CSV\\")\\n    l = commands.add_parser(\\"link-labels\\", help=\\"Link numbered validation rows to explicit OBJ scan IDs\\")\\n    b = commands.add_parser(\\"build-features\\", help=\\"Extract physical scan features directly from raw OBJs\\")\\n    t = commands.add_parser(\\"train\\", help=\\"Select per-measurement regressors using validation MAE\\")\\n    p = commands.add_parser(\\"predict\\", help=\\"Predict centimetres from scans without measurement metadata\\")\\n    for command in (a, t):\\n        command.add_argument(\\"--metadata\\", required=True, help=\\"Manual-measurement CSV or TSV\\")\\n        command.add_argument(\\"--id-col\\", required=command is t,\\n                             help=\\"Metadata column matching scan filenames/IDs; omit for index-only audit\\")\\n        command.add_argument(\\"--participant-col\\", help=\\"Stable person ID if each person can have multiple scan IDs\\")\\n        command.add_argument(\\"--config\\", required=command is t, help=\\"Explicit target-column and unit mapping JSON\\")\\n    for command in (a, t, p, i, l, b):\\n        command.add_argument(\\"--out-dir\\", required=True, help=\\"New or empty output directory\\")\\n    for command in (a, t, p):\\n        command.add_argument(\\"--features\\", required=command is not a, help=\\"Physical scan_geometry_features.npz\\")\\n    i.add_argument(\\"--metadata\\", required=True, help=\\"The numbered validation CSV\\")\\n    i.add_argument(\\"--obj-root\\", required=True, help=\\"Folder with original OBJs\\")\\n    i.add_argument(\\"--candidate-root\\", required=True, help=\\"Folder with possible mapping CSV/TSV files\\")\\n    l.add_argument(\\"--metadata\\", required=True, help=\\"The numbered validation CSV\\")\\n    l.add_argument(\\"--mapping\\", required=True, help=\\"Table with explicit row key and OBJ filename/code\\")\\n    l.add_argument(\\"--validation-row-col\\", default=\\"__row_number__\\",\\n                   help=\\"Validation row key; unnamed first header is called __row_number__\\")\\n    l.add_argument(\\"--map-row-col\\", required=True, help=\\"Mapping column with validation row key\\")\\n    l.add_argument(\\"--map-obj-col\\", required=True, help=\\"Mapping column with matching OBJ filename/code\\")\\n    l.add_argument(\\"--features\\", help=\\"Optional scan features; require every mapped OBJ to be present\\")\\n    b.add_argument(\\"--obj-root\\", required=True, help=\\"Recursively searched raw OBJ folder\\")\\n    b.add_argument(\\"--workers\\", type=int, default=2)\\n    b.add_argument(\\"--checkpoint-every\\", type=int, default=10)\\n    for command in (t, p):\\n        command.add_argument(\\"--scan-units\\", required=True, choices=(\\"mm\\", \\"cm\\", \\"m\\"),\\n                             help=\\"Actual raw OBJ coordinate units used to build this sidecar (not target units)\\")\\n    t.add_argument(\\"--seed\\", type=int, default=42)\\n    t.add_argument(\\"--test-fraction\\", type=float, default=0.2)\\n    t.add_argument(\\"--val-fraction\\", type=float, default=0.2, help=\\"Fraction of all participants\\")\\n    t.add_argument(\\"--splits\\", help=\\"Existing splits.csv to reuse a held-out cohort\\")\\n    t.add_argument(\\"--min-train-labels\\", type=int, default=10)\\n    t.add_argument(\\"--min-validation-labels\\", type=int, default=3)\\n    t.add_argument(\\"--n-estimators\\", type=int, default=300)\\n    t.add_argument(\\"--n-jobs\\", type=int, default=-1)\\n    p.add_argument(\\"--model\\", required=True, help=\\"Trusted model.joblib from train\\")\\n    a.set_defaults(handler=audit)\\n    i.set_defaults(handler=inspect_sources)\\n    l.set_defaults(handler=link_labels)\\n    b.set_defaults(handler=build_features)\\n    t.set_defaults(handler=train)\\n    p.set_defaults(handler=predict_new)\\n    return parser\\n\\n\\ndef main() -> None:\\n    parser = build_parser()\\n    args = parser.parse_args()\\n    try:\\n        args.handler(args)\\n    except (ValueError, KeyError, FileNotFoundError) as exc:\\n        parser.exit(2, f\\"Error: {exc}\\\\n\\")\\n\\n\\nif __name__ == \\"__main__\\":\\n    main()\\n","sha256":"f61afcebe456508efb367c68fc16b138cbe159458a39f1749d2a786dd78bdd30"},"scripts/preprocessing/build_scan_geometry_features.py":{"content":"#!/usr/bin/env python3\\n\\"\\"\\"Recover physical body-size features from raw OBJ files.\\n\\nThe existing combined NPZ was normalized separately for every participant, so\\nabsolute body dimensions were lost.  This script reads only OBJ vertex records\\n(it does not simplify meshes or resample points), writes resumable progress,\\nand creates a small sidecar aligned to the existing NPZ names array.\\n\\"\\"\\"\\nfrom __future__ import annotations\\n\\n# Allow direct execution as well as ``python -m`` from the repository checkout.\\nif __package__ in {None, \\"\\"}:\\n    import sys as _sys\\n    from pathlib import Path as _Path\\n    _sys.path.insert(0, str(_Path(__file__).resolve().parents[2]))\\n\\n\\nimport argparse\\nfrom concurrent.futures import ProcessPoolExecutor\\nimport csv\\nimport math\\nfrom pathlib import Path\\nimport time\\n\\nimport numpy as np\\nimport pandas as pd\\n\\nfrom meshvae.conditioning import clean_stregkode\\n\\n\\nFEATURE_NAMES = [\\n    \\"bbox_extent_x\\",\\n    \\"bbox_extent_y\\",\\n    \\"bbox_extent_z\\",\\n    \\"bbox_long\\",\\n    \\"bbox_mid\\",\\n    \\"bbox_short\\",\\n    \\"bbox_diagonal\\",\\n    \\"bbox_volume_cuberoot\\",\\n    \\"vertex_std_long\\",\\n    \\"vertex_std_mid\\",\\n    \\"vertex_std_short\\",\\n    \\"bbox_mid_to_long\\",\\n    \\"bbox_short_to_long\\",\\n    \\"log1p_vertex_count\\",\\n]\\n\\n\\ndef parse_obj_vertices(path_text: str) -> dict:\\n    path = Path(path_text)\\n    count = 0\\n    xyz_min = np.full(3, np.inf, dtype=np.float64)\\n    xyz_max = np.full(3, -np.inf, dtype=np.float64)\\n    xyz_sum = np.zeros(3, dtype=np.float64)\\n    outer_sum = np.zeros((3, 3), dtype=np.float64)\\n    try:\\n        with path.open(\\"r\\", encoding=\\"utf-8\\", errors=\\"ignore\\") as handle:\\n            for line in handle:\\n                if len(line) < 3 or line[0] != \\"v\\" or not line[1].isspace():\\n                    continue\\n                parts = line.split(maxsplit=4)\\n                if len(parts) < 4:\\n                    continue\\n                try:\\n                    xyz = np.asarray([float(parts[1]), float(parts[2]), float(parts[3])], dtype=np.float64)\\n                except ValueError:\\n                    continue\\n                if not np.isfinite(xyz).all():\\n                    continue\\n                count += 1\\n                xyz_min = np.minimum(xyz_min, xyz)\\n                xyz_max = np.maximum(xyz_max, xyz)\\n                xyz_sum += xyz\\n                outer_sum += np.outer(xyz, xyz)\\n\\n        if count < 4:\\n            raise ValueError(f\\"found only {count} valid vertices\\")\\n        extent = xyz_max - xyz_min\\n        if not np.isfinite(extent).all() or float(extent.max()) <= 0.0:\\n            raise ValueError(f\\"invalid bounding box {extent.tolist()}\\")\\n\\n        mean = xyz_sum / float(count)\\n        cov = (outer_sum / float(count)) - np.outer(mean, mean)\\n        cov = 0.5 * (cov + cov.T)\\n        eig = np.linalg.eigvalsh(cov)\\n        std_sorted = np.sqrt(np.maximum(eig, 0.0))[::-1]\\n        extent_sorted = np.sort(extent)[::-1]\\n        long, mid, short = [float(x) for x in extent_sorted]\\n        diag = float(np.linalg.norm(extent))\\n        volume_cuberoot = float(np.cbrt(max(float(np.prod(extent)), 0.0)))\\n        values = [\\n            float(extent[0]), float(extent[1]), float(extent[2]),\\n            long, mid, short, diag, volume_cuberoot,\\n            float(std_sorted[0]), float(std_sorted[1]), float(std_sorted[2]),\\n            mid / max(long, 1e-12), short / max(long, 1e-12), math.log1p(count),\\n        ]\\n        return {\\n            \\"path\\": str(path),\\n            \\"status\\": \\"ok\\",\\n            \\"error\\": \\"\\",\\n            \\"vertex_count\\": int(count),\\n            \\"scale_proxy\\": 0.5 * diag,\\n            **dict(zip(FEATURE_NAMES, values)),\\n        }\\n    except Exception as exc:\\n        return {\\n            \\"path\\": str(path),\\n            \\"status\\": \\"error\\",\\n            \\"error\\": str(exc),\\n            \\"vertex_count\\": int(count),\\n            \\"scale_proxy\\": np.nan,\\n            **{name: np.nan for name in FEATURE_NAMES},\\n        }\\n\\n\\ndef choose_obj_paths(roots: list[str]) -> dict[str, Path]:\\n    candidates: dict[str, list[Path]] = {}\\n    found = 0\\n    for raw_root in roots:\\n        root = Path(raw_root)\\n        if not root.exists():\\n            raise FileNotFoundError(f\\"OBJ root not found: {root}\\")\\n        paths = [root] if root.is_file() else root.rglob(\\"*.obj\\")\\n        for path in paths:\\n            found += 1\\n            code = clean_stregkode(path.name)\\n            if code:\\n                candidates.setdefault(code, []).append(path)\\n    print(f\\"[INDEX] found {found} OBJ files and {len(candidates)} cleaned participant IDs.\\", flush=True)\\n\\n    chosen = {}\\n    duplicate_ids = 0\\n    for code, paths in candidates.items():\\n        if len(paths) > 1:\\n            duplicate_ids += 1\\n        # Prefer a non-simplified file, then the largest file.  A raw scan is\\n        # normally much larger than a derived simplified copy.\\n        def rank(path: Path):\\n            simplified = \\"simplified\\" in path.name.lower() or \\"simplified\\" in str(path.parent).lower()\\n            try:\\n                size = path.stat().st_size\\n            except OSError:\\n                size = 0\\n            return (simplified, -size, str(path))\\n        chosen[code] = sorted(paths, key=rank)[0]\\n    print(f\\"[INDEX] duplicate IDs resolved deterministically: {duplicate_ids}.\\", flush=True)\\n    return chosen\\n\\n\\ndef load_partial(path: Path) -> dict[str, dict]:\\n    if not path.exists():\\n        return {}\\n    df = pd.read_csv(path)\\n    rows = {str(row[\\"code\\"]): row for row in df.to_dict(orient=\\"records\\") if row.get(\\"status\\") == \\"ok\\"}\\n    print(f\\"[RESUME] loaded {len(rows)} completed scans from {path}.\\", flush=True)\\n    return rows\\n\\n\\ndef write_partial(path: Path, rows: dict[str, dict]) -> None:\\n    path.parent.mkdir(parents=True, exist_ok=True)\\n    ordered = [rows[key] for key in sorted(rows)]\\n    pd.DataFrame(ordered).to_csv(path, index=False, quoting=csv.QUOTE_MINIMAL)\\n\\n\\ndef progress_line(done: int, total: int, started: float) -> str:\\n    elapsed = max(time.time() - started, 1e-6)\\n    rate = done / elapsed\\n    remaining = max(total - done, 0)\\n    eta_hours = (remaining / rate / 3600.0) if rate > 0 else float(\\"inf\\")\\n    return f\\"[PROGRESS] {done}/{total} ({100.0 * done / max(total, 1):.2f}%) ETA={eta_hours:.2f}h\\"\\n\\n\\ndef main() -> None:\\n    ap = argparse.ArgumentParser()\\n    ap.add_argument(\\"--npz\\", required=True, help=\\"Existing simplified_padded_tensors.npz\\")\\n    ap.add_argument(\\"--obj_roots\\", nargs=\\"+\\", required=True, help=\\"Raw OBJ roots searched recursively\\")\\n    ap.add_argument(\\"--out\\", default=None, help=\\"Output sidecar. Default: scan_geometry_features.npz beside --npz\\")\\n    ap.add_argument(\\"--partial_csv\\", default=None, help=\\"Resumable intermediate CSV path\\")\\n    ap.add_argument(\\"--workers\\", type=int, default=2)\\n    ap.add_argument(\\"--checkpoint_every\\", type=int, default=10)\\n    args = ap.parse_args()\\n\\n    npz_path = Path(args.npz)\\n    if not npz_path.exists():\\n        raise FileNotFoundError(npz_path)\\n    output = Path(args.out) if args.out else npz_path.parent / \\"scan_geometry_features.npz\\"\\n    partial = Path(args.partial_csv) if args.partial_csv else output.with_suffix(\\".partial.csv\\")\\n    packed = np.load(npz_path, allow_pickle=True)\\n    if \\"names\\" not in packed.files:\\n        raise KeyError(f\\"{npz_path} has no names array.\\")\\n    names = packed[\\"names\\"]\\n    requested_codes = [clean_stregkode(name) for name in names]\\n    requested_set = {code for code in requested_codes if code}\\n    print(f\\"[NPZ] {len(names)} rows, {len(requested_set)} unique usable IDs.\\", flush=True)\\n\\n    obj_by_code = choose_obj_paths(args.obj_roots)\\n    missing_obj = sorted(requested_set - set(obj_by_code))\\n    print(\\n        f\\"[MATCH] raw OBJ available for {len(requested_set) - len(missing_obj)}/{len(requested_set)} NPZ IDs; \\"\\n        f\\"missing {len(missing_obj)}.\\",\\n        flush=True,\\n    )\\n    if missing_obj:\\n        print(f\\"[MATCH] first missing OBJ IDs: {missing_obj[:30]}\\", flush=True)\\n\\n    completed = load_partial(partial)\\n    pending = [(code, obj_by_code[code]) for code in sorted(requested_set) if code in obj_by_code and code not in completed]\\n    print(f\\"[RUN] pending scans={len(pending)} workers={max(1, args.workers)}\\", flush=True)\\n    started = time.time()\\n    checkpoint_every = max(1, int(args.checkpoint_every))\\n\\n    if pending:\\n        with ProcessPoolExecutor(max_workers=max(1, int(args.workers))) as pool:\\n            paths = [str(path) for _, path in pending]\\n            for done, ((code, _), result) in enumerate(zip(pending, pool.map(parse_obj_vertices, paths)), start=1):\\n                completed[code] = {\\"code\\": code, **result}\\n                if result[\\"status\\"] != \\"ok\\":\\n                    print(f\\"[ERROR] {code}: {result[\'error\']} ({result[\'path\']})\\", flush=True)\\n                if done % checkpoint_every == 0 or done == len(pending):\\n                    write_partial(partial, completed)\\n                    print(progress_line(done, len(pending), started), flush=True)\\n\\n    feature_matrix = np.full((len(names), len(FEATURE_NAMES)), np.nan, dtype=np.float32)\\n    scale_proxy = np.full(len(names), np.nan, dtype=np.float32)\\n    valid = np.zeros(len(names), dtype=bool)\\n    source_paths = np.full(len(names), \\"\\", dtype=object)\\n    for i, code in enumerate(requested_codes):\\n        row = completed.get(str(code)) if code else None\\n        if not row or row.get(\\"status\\") != \\"ok\\":\\n            continue\\n        values = np.asarray([row[name] for name in FEATURE_NAMES], dtype=np.float32)\\n        scale = float(row[\\"scale_proxy\\"])\\n        if not np.isfinite(values).all() or not np.isfinite(scale) or scale <= 0.0:\\n            continue\\n        feature_matrix[i] = values\\n        scale_proxy[i] = scale\\n        valid[i] = True\\n        source_paths[i] = str(row[\\"path\\"])\\n\\n    output.parent.mkdir(parents=True, exist_ok=True)\\n    np.savez_compressed(\\n        output,\\n        names=np.asarray(names, dtype=object),\\n        features=feature_matrix,\\n        feature_names=np.asarray(FEATURE_NAMES, dtype=object),\\n        scale_proxy=scale_proxy,\\n        valid=valid,\\n        source_paths=source_paths,\\n    )\\n    audit = pd.DataFrame(feature_matrix[valid], columns=FEATURE_NAMES).describe(percentiles=[0.01, 0.05, 0.5, 0.95, 0.99]).T\\n    audit_path = output.with_name(output.stem + \\"_audit.csv\\")\\n    audit.to_csv(audit_path)\\n    print(f\\"[OUT] sidecar -> {output} valid={int(valid.sum())}/{len(valid)}\\", flush=True)\\n    print(f\\"[OUT] audit   -> {audit_path}\\", flush=True)\\n    print(f\\"[OUT] resume  -> {partial}\\", flush=True)\\n    if bool(valid.any()):\\n        qs = np.quantile(scale_proxy[valid], [0.01, 0.5, 0.99])\\n        print(f\\"[AUDIT] scale_proxy p01={qs[0]:.3f} median={qs[1]:.3f} p99={qs[2]:.3f}\\", flush=True)\\n\\n\\nif __name__ == \\"__main__\\":\\n    main()\\n","sha256":"2fa463013d9e6250167bea75fb31e00c2d38caa2c9773e3a34455ef89387a2ef"},"body_measurements/__init__.py":{"content":"\\"\\"\\"Supervised prediction of manual body measurements from scan geometry.\\"\\"\\"\\n\\n__version__ = \\"0.1.0\\"\\n","sha256":"aa72db8921c08bac60e888f8bec60878e21c947e16693169330834791b57cef5"},"body_measurements/data.py":{"content":"\\"\\"\\"Strict scan/metadata alignment, explicit target units, and person-level splits.\\"\\"\\"\\nfrom __future__ import annotations\\n\\nimport csv\\nimport io\\nimport json\\nimport re\\nfrom pathlib import Path\\n\\nimport numpy as np\\nimport pandas as pd\\n\\n\\n_DET_ID = re.compile(r\\"([A-Z]+DET\\\\d{5,10})\\", re.IGNORECASE)\\n_NULL_TEXT = {\\"\\", \\"nan\\", \\"none\\", \\"null\\", \\"na\\", \\"n/a\\", \\"<na>\\", \\"nat\\"}\\n_TO_CM = {\\"cm\\": 1.0, \\"mm\\": 0.1, \\"m\\": 100.0}\\n_SCAN_SUFFIXES = {\\".obj\\", \\".ply\\", \\".stl\\", \\".off\\", \\".npz\\", \\".npy\\"}\\nUNNAMED_ROW_COLUMN = \\"__row_number__\\"\\n\\n\\ndef _text(value) -> str | None:\\n    if value is None or pd.isna(value):\\n        return None\\n    if isinstance(value, bytes):\\n        value = value.decode(\\"utf-8\\")\\n    if isinstance(value, (float, np.floating)) and float(value).is_integer():\\n        value = int(value)\\n    result = str(value).strip().strip(\'\\"\').strip(\\"\'\\").strip()\\n    return None if result.casefold() in _NULL_TEXT else result\\n\\n\\ndef clean_id(value) -> str | None:\\n    \\"\\"\\"Extract legacy DET IDs, or retain a generic identifier/file stem.\\n\\n    Generic identifiers are case sensitive and leading zeroes are preserved.\\n    DET extraction follows the existing repository\'s scan naming convention.\\n    Any collisions introduced by extraction are rejected during alignment.\\n    \\"\\"\\"\\n    value = _text(value)\\n    if value is None:\\n        return None\\n    basename = value.replace(\\"\\\\\\\\\\", \\"/\\").rsplit(\\"/\\", 1)[-1]\\n    match = _DET_ID.search(basename)\\n    if match:\\n        return match.group(1).upper()\\n    suffix = Path(basename).suffix\\n    if suffix.lower() in _SCAN_SUFFIXES:\\n        basename = basename[:-len(suffix)]\\n    return _text(basename)\\n\\n\\ndef clean_participant_id(value) -> str | None:\\n    \\"\\"\\"Preserve an explicit person\'s ID, including slashes and DET substrings.\\"\\"\\"\\n    return _text(value)\\n\\n\\ndef load_config(path: str | Path) -> list[dict]:\\n    \\"\\"\\"Read active target mappings; every active target needs explicit units.\\"\\"\\"\\n    raw = json.loads(Path(path).read_text(encoding=\\"utf-8-sig\\"))\\n    definitions = raw.get(\\"targets\\") if isinstance(raw, dict) else None\\n    if not isinstance(definitions, dict):\\n        raise ValueError(\\"Target config must contain an object named \'targets\'.\\")\\n    result: list[dict] = []\\n    used_columns: set[str] = set()\\n    for name, specification in definitions.items():\\n        if not isinstance(name, str) or not name.strip():\\n            raise ValueError(\\"Target names must be nonempty strings.\\")\\n        if not isinstance(specification, dict):\\n            raise ValueError(f\\"Target {name!r} must be an object.\\")\\n        column = specification.get(\\"column\\")\\n        if column is None:\\n            continue\\n        if not isinstance(column, str) or not column.strip():\\n            raise ValueError(f\\"Target {name!r} needs a nonempty metadata column.\\")\\n        if column in used_columns:\\n            raise ValueError(f\\"Metadata column {column!r} is mapped to more than one target.\\")\\n        unit = specification.get(\\"unit\\")\\n        if not isinstance(unit, str) or unit not in _TO_CM:\\n            raise ValueError(f\\"Target {name!r} requires an explicit unit: cm, mm, or m.\\")\\n        target = {**specification, \\"name\\": name, \\"column\\": column, \\"unit\\": unit}\\n        for bound in (\\"min_cm\\", \\"max_cm\\"):\\n            if target.get(bound) is not None:\\n                try:\\n                    target[bound] = float(target[bound])\\n                except (TypeError, ValueError) as exc:\\n                    raise ValueError(f\\"Target {name!r}: {bound} must be numeric.\\") from exc\\n                if not np.isfinite(target[bound]) or target[bound] <= 0:\\n                    raise ValueError(f\\"Target {name!r}: {bound} must be finite and positive.\\")\\n        if (target.get(\\"min_cm\\") is not None and target.get(\\"max_cm\\") is not None\\n                and target[\\"min_cm\\"] > target[\\"max_cm\\"]):\\n            raise ValueError(f\\"Target {name!r}: min_cm exceeds max_cm.\\")\\n        used_columns.add(column)\\n        result.append(target)\\n    if not result:\\n        raise ValueError(\\"No active targets: set at least one column and its unit in the config.\\")\\n    return result\\n\\n\\ndef read_metadata(path: str | Path) -> pd.DataFrame:\\n    \\"\\"\\"Read quoted TSV/CSV exports without silently dropping malformed rows.\\n\\n    Values stay as strings so identifiers retain leading zeroes and decimal\\n    commas can be interpreted only after the delimiter has been resolved.\\n    \\"\\"\\"\\n    path = Path(path)\\n    contents = path.read_bytes()\\n    try:\\n        text = contents.decode(\\"utf-8-sig\\")\\n        encoding = \\"utf-8-sig\\"\\n    except UnicodeDecodeError:\\n        text = contents.decode(\\"cp1252\\")\\n        encoding = \\"cp1252\\"\\n    if \\"\\\\x00\\" in text:\\n        raise ValueError(f\\"{path}: unsupported encoding; export as UTF-8 TSV/CSV.\\")\\n    if not text.strip():\\n        raise ValueError(f\\"{path}: metadata is empty.\\")\\n\\n    # Inspect the parsed header for each delimiter: separators inside quotes\\n    # must not influence detection, nor should decimal commas in later rows.\\n    candidates = []\\n    for delimiter in (\\"\\\\t\\", \\";\\", \\",\\"):\\n        try:\\n            reader = csv.reader(io.StringIO(text, newline=\\"\\"), delimiter=delimiter, strict=True)\\n            header = next((row for row in reader if row), [])\\n            candidates.append((len(header), delimiter))\\n        except csv.Error:\\n            continue\\n    if not candidates:\\n        raise ValueError(f\\"{path}: cannot parse the metadata header.\\")\\n    width, delimiter = max(candidates, key=lambda item: item[0])\\n    if width == 0:\\n        raise ValueError(f\\"{path}: metadata has no header.\\")\\n    reader = csv.reader(io.StringIO(text, newline=\\"\\"), delimiter=delimiter, strict=True)\\n    header = None\\n    rows = []\\n    try:\\n        for row in reader:\\n            if not row:\\n                continue\\n            if header is None:\\n                header = [value.lstrip(\\"\\\\ufeff\\").strip() for value in row]\\n                # pandas-exported row indices often have an empty first header.\\n                # Give that field an explicit name, but never treat it as a scan ID.\\n                if header and header[0] == \\"\\":\\n                    header[0] = UNNAMED_ROW_COLUMN\\n                if any(not value for value in header) or len(set(header)) != len(header):\\n                    raise ValueError(f\\"{path}: metadata column names must be nonempty and unique.\\")\\n                continue\\n            if len(row) != len(header):\\n                raise ValueError(\\n                    f\\"{path}: malformed metadata row ending at line {reader.line_num}: \\"\\n                    f\\"expected {len(header)} fields, found {len(row)}.\\"\\n                )\\n            rows.append(row)\\n    except csv.Error as exc:\\n        raise ValueError(f\\"{path}: malformed CSV near line {reader.line_num}: {exc}\\") from exc\\n    result = pd.DataFrame(rows, columns=header, dtype=str)\\n    result.attrs.update({\\"encoding\\": encoding, \\"delimiter\\": delimiter})\\n    return result\\n\\n\\ndef load_features(path: str | Path) -> tuple[pd.DataFrame, dict]:\\n    \\"\\"\\"Load physical geometry sidecars and discard explicitly invalid rows.\\n\\n    Existing sidecars store names as object arrays, so only load trusted local\\n    files. The feature matrix is never augmented with labels or metadata.\\n    \\"\\"\\"\\n    path = Path(path)\\n    with np.load(path, allow_pickle=True) as data:\\n        required = {\\"names\\", \\"features\\", \\"feature_names\\"}\\n        missing = required - set(data.files)\\n        if missing:\\n            raise ValueError(f\\"{path}: missing arrays {sorted(missing)}.\\")\\n        names = data[\\"names\\"]\\n        raw_feature_names = data[\\"feature_names\\"]\\n        try:\\n            values = np.asarray(data[\\"features\\"], dtype=np.float64)\\n        except (TypeError, ValueError) as exc:\\n            raise ValueError(f\\"{path}: features must be numeric.\\") from exc\\n        if names.ndim != 1 or raw_feature_names.ndim != 1 or values.ndim != 2:\\n            raise ValueError(f\\"{path}: names/feature_names must be vectors and features a matrix.\\")\\n        if values.shape != (len(names), len(raw_feature_names)) or not len(raw_feature_names):\\n            raise ValueError(f\\"{path}: feature names, scan names, and matrix dimensions disagree.\\")\\n        feature_names = [v.decode(\\"utf-8\\") if isinstance(v, bytes) else str(v)\\n                         for v in raw_feature_names]\\n        if (any(not value.strip() for value in feature_names)\\n                or len(set(feature_names)) != len(feature_names)):\\n            raise ValueError(f\\"{path}: feature names must be nonempty and unique.\\")\\n        ids = [clean_id(value) for value in names]\\n        if any(value is None for value in ids):\\n            raise ValueError(f\\"{path}: scan names contain missing identifiers.\\")\\n        if len(set(ids)) != len(ids):\\n            raise ValueError(f\\"{path}: duplicate scan IDs after cleaning; resolve repeated scans explicitly.\\")\\n        valid = np.isfinite(values).all(axis=1)\\n        nonfinite_rows = int((~valid).sum())\\n        flagged_invalid_rows = 0\\n        invalid_scale_rows = 0\\n        if \\"valid\\" in data.files:\\n            declared = data[\\"valid\\"]\\n            if declared.shape != (len(names),) or not np.isin(declared, [False, True]).all():\\n                raise ValueError(f\\"{path}: valid must be a boolean (or 0/1) vector with one entry per scan.\\")\\n            declared = declared.astype(bool)\\n            flagged_invalid_rows = int((~declared).sum())\\n            valid &= declared\\n        if \\"scale_proxy\\" in data.files:\\n            try:\\n                scale = np.asarray(data[\\"scale_proxy\\"], dtype=float)\\n            except (TypeError, ValueError) as exc:\\n                raise ValueError(f\\"{path}: scale_proxy must be numeric.\\") from exc\\n            if scale.shape != (len(names),):\\n                raise ValueError(f\\"{path}: scale_proxy must have one entry per scan.\\")\\n            valid_scale = np.isfinite(scale) & (scale > 0)\\n            invalid_scale_rows = int((~valid_scale).sum())\\n            valid &= valid_scale\\n    frame = pd.DataFrame(values[valid], index=pd.Index(np.asarray(ids)[valid], name=\\"scan_id\\"),\\n                         columns=feature_names)\\n    audit = {\\"rows_total\\": len(ids), \\"rows_valid\\": int(valid.sum()),\\n             \\"rows_invalid\\": int((~valid).sum()), \\"nonfinite_feature_rows\\": nonfinite_rows,\\n             \\"flagged_invalid_rows\\": flagged_invalid_rows, \\"invalid_scale_rows\\": invalid_scale_rows,\\n             \\"feature_names\\": feature_names}\\n    return frame, audit\\n\\n\\ndef align_training(\\n    features: pd.DataFrame, metadata: pd.DataFrame, targets: list[dict],\\n    id_col: str, participant_col: str | None = None,\\n) -> tuple[pd.DataFrame, pd.DataFrame, pd.Series, dict]:\\n    \\"\\"\\"Match unique scans, mask unavailable labels, and retain person groups.\\"\\"\\"\\n    if not targets:\\n        raise ValueError(\\"At least one active target is required.\\")\\n    if not metadata.columns.is_unique or not features.index.is_unique:\\n        raise ValueError(\\"Metadata columns and feature scan IDs must be unique.\\")\\n    required = {id_col, *(target[\\"column\\"] for target in targets)}\\n    if participant_col is not None:\\n        required.add(participant_col)\\n    missing = required - set(metadata.columns)\\n    if missing:\\n        raise ValueError(f\\"Metadata is missing requested columns: {sorted(missing)}.\\")\\n    ids = metadata[id_col].map(clean_id)\\n    duplicate = ids.notna() & ids.duplicated(keep=False)\\n    if duplicate.any():\\n        raise ValueError(\\n            f\\"Duplicate metadata scan IDs after cleaning ({int(duplicate.sum())} rows). \\"\\n            \\"Resolve repeated visits/scans explicitly before training.\\"\\n        )\\n    available = metadata.loc[ids.notna()].copy()\\n    available.index = pd.Index(ids.loc[ids.notna()].tolist(), name=\\"scan_id\\")\\n    matched_ids = features.index[features.index.isin(available.index)]\\n    aligned = available.loc[matched_ids]\\n    X = features.loc[matched_ids].copy()\\n    if participant_col is None:\\n        groups = pd.Series(matched_ids.astype(str), index=matched_ids, name=\\"participant_id\\")\\n    else:\\n        groups = aligned[participant_col].map(clean_participant_id).rename(\\"participant_id\\")\\n        if groups.isna().any():\\n            raise ValueError(\\"Matched metadata rows have missing participant IDs; person-level splitting is unsafe.\\")\\n    y = pd.DataFrame(index=matched_ids)\\n    target_audit = {}\\n    for target in targets:\\n        name, column, unit = target[\\"name\\"], target[\\"column\\"], target[\\"unit\\"]\\n        if unit not in _TO_CM:\\n            raise ValueError(f\\"Target {name!r}: unsupported unit {unit!r}.\\")\\n        raw = aligned[column].map(_text)\\n        decimal_text = raw.map(lambda value: value.replace(\\",\\", \\".\\") if value is not None else None)\\n        numbers = pd.to_numeric(decimal_text, errors=\\"coerce\\").astype(float)\\n        numbers *= _TO_CM[unit]\\n        finite = pd.Series(np.isfinite(numbers.to_numpy()), index=numbers.index)\\n        positive = finite & (numbers > 0)\\n        below = positive & (numbers < target[\\"min_cm\\"]) if target.get(\\"min_cm\\") is not None else positive & False\\n        above = positive & (numbers > target[\\"max_cm\\"]) if target.get(\\"max_cm\\") is not None else positive & False\\n        valid = positive & ~below & ~above\\n        y[name] = numbers.where(valid)\\n        target_audit[name] = {\\n            \\"column\\": column, \\"unit\\": unit, \\"output_unit\\": \\"cm\\",\\n            \\"available\\": int(valid.sum()), \\"missing\\": int((~valid).sum()),\\n            \\"coverage_fraction\\": float(valid.mean()) if len(valid) else 0.0,\\n            \\"source_missing\\": int(raw.isna().sum()),\\n            \\"invalid_numeric\\": int((raw.notna() & ~finite).sum()),\\n            \\"nonpositive\\": int((finite & (numbers <= 0)).sum()),\\n            \\"below_min\\": int(below.sum()), \\"above_max\\": int(above.sum()),\\n        }\\n    keep = y.notna().any(axis=1)\\n    audit = {\\n        \\"metadata_rows_total\\": len(metadata), \\"metadata_rows_empty_id\\": int(ids.isna().sum()),\\n        \\"metadata_rows_without_scan\\": int((~available.index.isin(features.index)).sum()),\\n        \\"feature_rows_total\\": len(features), \\"matched_rows\\": len(matched_ids),\\n        \\"feature_rows_without_metadata\\": len(features) - len(matched_ids),\\n        \\"rows_without_any_target\\": int((~keep).sum()), \\"rows_retained\\": int(keep.sum()),\\n        \\"participants_retained\\": int(groups.loc[keep].nunique()), \\"targets\\": target_audit,\\n        \\"participant_column\\": participant_col,\\n    }\\n    return X.loc[keep], y.loc[keep], groups.loc[keep], audit\\n\\n\\ndef make_splits(\\n    groups: pd.Series, seed: int, test_fraction: float = 0.2, val_fraction: float = 0.2,\\n) -> pd.Series:\\n    \\"\\"\\"Assign complete participants to deterministic train/validation/test sets.\\n\\n    Fractions apply to participant counts. Each held-out set receives at least\\n    one person; flooring leaves the remaining participants in training.\\n    \\"\\"\\"\\n    if (not np.isfinite(test_fraction) or not np.isfinite(val_fraction)\\n            or test_fraction <= 0 or val_fraction <= 0 or test_fraction + val_fraction >= 1):\\n        raise ValueError(\\"Split fractions must be positive and leave a positive training fraction.\\")\\n    normalized = groups.map(clean_participant_id)\\n    if normalized.isna().any():\\n        raise ValueError(\\"Participant groups cannot be missing.\\")\\n    participants = np.asarray(sorted(normalized.unique()), dtype=object)\\n    if len(participants) < 3:\\n        raise ValueError(\\"At least three participants are required for train/validation/test splitting.\\")\\n    n_test = max(1, int(np.floor(len(participants) * test_fraction)))\\n    n_val = max(1, int(np.floor(len(participants) * val_fraction)))\\n    if n_test + n_val >= len(participants):\\n        raise ValueError(\\"Insufficient participants for the requested split fractions.\\")\\n    shuffled = np.random.default_rng(seed).permutation(participants)\\n    mapping = {participant: \\"train\\" for participant in participants}\\n    mapping.update({participant: \\"test\\" for participant in shuffled[:n_test]})\\n    mapping.update({participant: \\"validation\\" for participant in shuffled[n_test:n_test + n_val]})\\n    return normalized.map(mapping).rename(\\"split\\")\\n","sha256":"71f12f27dd1c1ba4af5315c8f0217c4bb79ab11e7d02bdd046a95a927aa545bf"},"body_measurements/joins.py":{"content":"\\"\\"\\"Explicitly link numbered validation rows to OBJ scan identifiers.\\"\\"\\"\\nfrom __future__ import annotations\\n\\nfrom pathlib import Path\\n\\nimport pandas as pd\\n\\nfrom .data import UNNAMED_ROW_COLUMN, clean_id, read_metadata\\n\\n\\ndef _unique_nonempty(series: pd.Series, label: str, normalizer) -> pd.Series:\\n    values = series.map(normalizer)\\n    if values.isna().any():\\n        raise ValueError(f\\"{label} has {int(values.isna().sum())} empty values\\")\\n    if values.duplicated().any():\\n        examples = values[values.duplicated(keep=False)].unique().tolist()[:10]\\n        raise ValueError(f\\"{label} has duplicate IDs: {examples}\\")\\n    return values\\n\\n\\ndef link_validation_rows(\\n    validation: pd.DataFrame,\\n    mapping: pd.DataFrame,\\n    *,\\n    validation_row_col: str = UNNAMED_ROW_COLUMN,\\n    map_row_col: str,\\n    map_obj_col: str,\\n    available_scan_ids: set[str] | None = None,\\n) -> tuple[pd.DataFrame, dict]:\\n    \\"\\"\\"Join by an explicit shared row key, rejecting ambiguous and unmatched rows.\\"\\"\\"\\n    if not validation.columns.is_unique or not mapping.columns.is_unique:\\n        raise ValueError(\\"Validation and mapping columns must be unique\\")\\n    if validation_row_col not in validation:\\n        raise ValueError(f\\"Validation row column {validation_row_col!r} absent: {list(validation)}\\")\\n    for column in (map_row_col, map_obj_col):\\n        if column not in mapping:\\n            raise ValueError(f\\"Mapping column {column!r} absent: {list(mapping)}\\")\\n    if \\"scan_id\\" in validation and validation_row_col != \\"scan_id\\":\\n        raise ValueError(\\"Validation table already has a scan_id column; use that directly after auditing it\\")\\n\\n    def row_key(value) -> str | None:\\n        if value is None or pd.isna(value):\\n            return None\\n        result = str(value).strip()\\n        return result if result and result.casefold() not in {\\"nan\\", \\"none\\", \\"null\\"} else None\\n\\n    validation_key = _unique_nonempty(validation[validation_row_col], \\"validation row key\\", row_key)\\n    mapping_key = _unique_nonempty(mapping[map_row_col], \\"mapping row key\\", row_key)\\n    scan_ids = _unique_nonempty(mapping[map_obj_col], \\"mapping OBJ\\", clean_id)\\n    by_key = pd.Series(scan_ids.to_numpy(), index=mapping_key.to_numpy())\\n    missing = validation_key[~validation_key.isin(by_key.index)].tolist()\\n    if missing:\\n        raise ValueError(f\\"Mapping lacks {len(missing)} validation row keys; examples: {missing[:10]}\\")\\n    linked_ids = by_key.loc[validation_key.to_numpy()].to_numpy()\\n    extra_mapping = len(set(mapping_key) - set(validation_key))\\n    if available_scan_ids is not None:\\n        absent = sorted(set(linked_ids) - available_scan_ids)\\n        if absent:\\n            raise ValueError(f\\"{len(absent)} mapped OBJ IDs have no scan features; examples: {absent[:10]}\\")\\n    if \\"scan_id\\" in validation.columns:\\n        raise ValueError(\\"Validation metadata already contains scan_id\\")\\n    linked = validation.copy()\\n    linked.insert(0, \\"scan_id\\", linked_ids)\\n    audit = {\\n        \\"validation_rows\\": len(validation), \\"mapping_rows\\": len(mapping),\\n        \\"joined_rows\\": len(linked), \\"mapping_rows_not_in_validation\\": extra_mapping,\\n        \\"unique_scan_ids\\": len(set(linked_ids)),\\n        \\"validation_row_col\\": validation_row_col, \\"map_row_col\\": map_row_col,\\n        \\"map_obj_col\\": map_obj_col,\\n    }\\n    return linked, audit\\n\\n\\ndef scan_candidate_tables(\\n    validation_path: str | Path,\\n    obj_root: str | Path,\\n    candidate_root: str | Path,\\n) -> pd.DataFrame:\\n    \\"\\"\\"Summarize nearby CSV/TSV headers and overlaps without guessing a join.\\"\\"\\"\\n    validation = read_metadata(validation_path)\\n    candidate_root = Path(candidate_root)\\n    obj_root = Path(obj_root)\\n    if not candidate_root.is_dir() or not obj_root.is_dir():\\n        raise FileNotFoundError(\\"Candidate root and OBJ root must both exist\\")\\n    scan_ids = {clean_id(path.name) for path in obj_root.rglob(\\"*\\")\\n                if path.is_file() and path.suffix.lower() == \\".obj\\"}\\n    scan_ids.discard(None)\\n    measure_cols = set(validation.columns) - {UNNAMED_ROW_COLUMN}\\n    rows = []\\n    for path in sorted(candidate_root.iterdir()):\\n        if not path.is_file() or path.suffix.lower() not in {\\".csv\\", \\".tsv\\"} or path == Path(validation_path):\\n            continue\\n        try:\\n            table = read_metadata(path)\\n            per_column = {}\\n            for column in table:\\n                ids = set(table[column].map(clean_id).dropna()) & scan_ids\\n                if ids:\\n                    per_column[column] = len(ids)\\n            row_candidates = []\\n            if UNNAMED_ROW_COLUMN in validation:\\n                expected = set(validation[UNNAMED_ROW_COLUMN].astype(str).str.strip())\\n                for column in table:\\n                    values = table[column].astype(str).str.strip()\\n                    overlap = len(set(values) & expected)\\n                    if overlap:\\n                        row_candidates.append((column, overlap))\\n            rows.append({\\n                \\"path\\": str(path), \\"rows\\": len(table),\\n                \\"measurement_headers_shared\\": len(measure_cols & set(table.columns)),\\n                \\"best_obj_column\\": max(per_column, key=per_column.get) if per_column else \\"\\",\\n                \\"best_obj_matches\\": max(per_column.values(), default=0),\\n                \\"best_row_column\\": max(row_candidates, key=lambda pair: pair[1])[0] if row_candidates else \\"\\",\\n                \\"best_row_matches\\": max((overlap for _, overlap in row_candidates), default=0),\\n                \\"columns\\": \\" | \\".join(table.columns), \\"error\\": \\"\\",\\n            })\\n        except (ValueError, UnicodeError) as exc:\\n            rows.append({\\"path\\": str(path), \\"error\\": str(exc)})\\n    result = pd.DataFrame(rows)\\n    if len(result):\\n        result.sort_values([\\"best_obj_matches\\", \\"best_row_matches\\", \\"measurement_headers_shared\\"],\\n                           ascending=False, na_position=\\"last\\", inplace=True)\\n    return result\\n","sha256":"6a1b9fe39f0a25d088b0c47f6ef314ecb0298035146a61fd95188d1f33b45a7a"},"body_measurements/models.py":{"content":"\\"\\"\\"Leakage-conscious baselines for predicting manual measurements in centimetres.\\n\\nOnly scan-derived numeric features belong in ``X``. The data preparation layer\\nis responsible for excluding metadata, identifiers, and target-derived features.\\nEach candidate is fitted on labelled training rows for its own target; validation\\nselects a model and the held-out test partition is used only for reporting.\\n\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nimport numpy as np\\nimport pandas as pd\\nfrom sklearn.dummy import DummyRegressor\\nfrom sklearn.ensemble import ExtraTreesRegressor\\nfrom sklearn.linear_model import Ridge\\nfrom sklearn.pipeline import make_pipeline\\nfrom sklearn.preprocessing import StandardScaler\\n\\n\\nFORMAT_VERSION = 1\\n_PARTITIONS = (\\"train\\", \\"validation\\", \\"test\\")\\n\\n\\ndef _numeric_features(X: pd.DataFrame) -> pd.DataFrame:\\n    if not isinstance(X, pd.DataFrame):\\n        raise TypeError(\\"X must be a pandas DataFrame with named scan geometry features.\\")\\n    if X.shape[1] == 0:\\n        raise ValueError(\\"At least one scan geometry feature is required.\\")\\n    if not X.index.is_unique or not X.columns.is_unique:\\n        raise ValueError(\\"Feature row identifiers and column names must be unique.\\")\\n    if not all(isinstance(name, str) for name in X.columns):\\n        raise ValueError(\\"Feature names must be strings.\\")\\n    try:\\n        numeric = X.astype(float)\\n    except (TypeError, ValueError) as exc:\\n        raise ValueError(\\"Scan geometry features must be numeric.\\") from exc\\n    if not np.isfinite(numeric.to_numpy()).all():\\n        raise ValueError(\\"Scan geometry features contain missing or nonfinite values.\\")\\n    return numeric\\n\\n\\ndef _align_rows(value: pd.DataFrame | pd.Series, X: pd.DataFrame, name: str):\\n    if not value.index.is_unique:\\n        raise ValueError(f\\"{name} row identifiers must be unique.\\")\\n    if len(value) != len(X) or not X.index.isin(value.index).all():\\n        raise ValueError(f\\"{name} must have exactly the same scan identifiers as X.\\")\\n    return value.reindex(X.index)\\n\\n\\ndef _regression_metrics(actual: np.ndarray, predicted: np.ndarray) -> dict:\\n    labelled = np.isfinite(actual)\\n    actual, predicted = actual[labelled], predicted[labelled]\\n    n = len(actual)\\n    result = dict.fromkeys(\\n        (\\"mae_cm\\", \\"rmse_cm\\", \\"r2\\", \\"bias_cm\\", \\"loa_lower_cm\\", \\"loa_upper_cm\\",\\n         \\"within_1_cm\\", \\"within_2_cm\\"), float(\\"nan\\")\\n    )\\n    result[\\"n\\"] = n\\n    if not n:\\n        return result\\n    residual = predicted - actual\\n    bias = float(residual.mean())\\n    result.update(\\n        mae_cm=float(np.abs(residual).mean()),\\n        rmse_cm=float(np.sqrt(np.square(residual).mean())),\\n        bias_cm=bias,\\n        within_1_cm=float((np.abs(residual) <= 1.0).mean()),\\n        within_2_cm=float((np.abs(residual) <= 2.0).mean()),\\n    )\\n    if n >= 2:\\n        spread = 1.96 * float(residual.std(ddof=1))\\n        result.update(loa_lower_cm=bias - spread, loa_upper_cm=bias + spread)\\n        denominator = float(np.square(actual - actual.mean()).sum())\\n        if denominator > 0:\\n            result[\\"r2\\"] = float(1.0 - np.square(residual).sum() / denominator)\\n    return result\\n\\n\\ndef fit_models(\\n    X: pd.DataFrame,\\n    y: pd.DataFrame,\\n    split: pd.Series,\\n    *,\\n    seed: int = 42,\\n    min_train_labels: int = 10,\\n    min_validation_labels: int = 3,\\n    n_estimators: int = 300,\\n    n_jobs: int = -1,\\n) -> tuple[dict, pd.DataFrame, pd.DataFrame, pd.DataFrame]:\\n    \\"\\"\\"Fit training-only models and return bundle, metrics, predictions, selection.\\n\\n    Targets must already be expressed in centimetres. Missing targets are masked\\n    independently. A target with insufficient training labels is skipped; with\\n    insufficient validation labels its training median is the selected fallback.\\n    Validation MAE selects among the median, four scaled Ridge regressions, and\\n    Extra Trees. Ties prefer the first candidate, starting with the median.\\n    No model is refitted after selection. Validation reports every candidate;\\n    test reports only the selected model and the median comparator. Metrics use\\n    labelled rows; predictions also include unlabelled rows from those splits.\\n    \\"\\"\\"\\n    X = _numeric_features(X)\\n    if not isinstance(y, pd.DataFrame) or not isinstance(split, pd.Series):\\n        raise TypeError(\\"y must be a DataFrame and split must be a Series.\\")\\n    if not y.columns.is_unique or not all(isinstance(name, str) for name in y.columns):\\n        raise ValueError(\\"Target names must be unique strings.\\")\\n    if y.shape[1] == 0:\\n        raise ValueError(\\"At least one measurement target is required.\\")\\n    y = _align_rows(y, X, \\"Targets\\")\\n    split = _align_rows(split, X, \\"Split\\")\\n    try:\\n        y = y.astype(float)\\n    except (TypeError, ValueError) as exc:\\n        raise ValueError(\\"Measurement targets must be numeric centimetres or missing.\\") from exc\\n    if np.isinf(y.to_numpy()).any():\\n        raise ValueError(\\"Measurement targets cannot contain infinite values.\\")\\n    if not split.isin(_PARTITIONS).all():\\n        raise ValueError(\\"Split labels must be train, validation, or test with no missing values.\\")\\n    for name, value in ((\\"min_train_labels\\", min_train_labels),\\n                        (\\"min_validation_labels\\", min_validation_labels),\\n                        (\\"n_estimators\\", n_estimators)):\\n        if isinstance(value, bool) or not isinstance(value, (int, np.integer)) or value < 1:\\n            raise ValueError(f\\"{name} must be a positive integer.\\")\\n    train = split.eq(\\"train\\")\\n    if not train.any():\\n        raise ValueError(\\"A nonempty training partition is required.\\")\\n\\n    selected_models: dict = {}\\n    metric_rows: list[dict] = []\\n    prediction_frames: list[pd.DataFrame] = []\\n    selection_rows: list[dict] = []\\n    for target in y.columns:\\n        labelled = y[target].notna()\\n        counts = {part: int((split.eq(part) & labelled).sum()) for part in _PARTITIONS}\\n        selection = {\\n            \\"target\\": target,\\n            \\"n_train\\": counts[\\"train\\"],\\n            \\"n_validation\\": counts[\\"validation\\"],\\n            \\"n_test\\": counts[\\"test\\"],\\n            \\"selected_model\\": None,\\n            \\"validation_mae_cm\\": float(\\"nan\\"),\\n        }\\n        if counts[\\"train\\"] < min_train_labels:\\n            selection.update(\\n                status=\\"skipped\\",\\n                reason=f\\"Only {counts[\'train\']} training labels; need {min_train_labels}.\\",\\n            )\\n            selection_rows.append(selection)\\n            continue\\n\\n        candidates = {\\"train_median\\": DummyRegressor(strategy=\\"median\\")}\\n        for alpha in (0.1, 1, 10, 100):\\n            candidates[f\\"ridge_alpha_{alpha}\\"] = make_pipeline(StandardScaler(), Ridge(alpha=alpha))\\n        candidates[\\"extra_trees\\"] = ExtraTreesRegressor(\\n            n_estimators=n_estimators, min_samples_leaf=2, random_state=seed, n_jobs=n_jobs\\n        )\\n        train_labelled = train & labelled\\n        for estimator in candidates.values():\\n            estimator.fit(X.loc[train_labelled], y.loc[train_labelled, target])\\n\\n        # Complete selection before inspecting test outcomes or computing test metrics.\\n        validation = split.eq(\\"validation\\")\\n        validation_predictions = {\\n            name: estimator.predict(X.loc[validation]) if validation.any() else np.empty(0)\\n            for name, estimator in candidates.items()\\n        }\\n        validation_metrics = {\\n            name: _regression_metrics(y.loc[validation, target].to_numpy(), predicted)\\n            for name, predicted in validation_predictions.items()\\n        }\\n        if counts[\\"validation\\"] >= min_validation_labels:\\n            selected_name = min(candidates, key=lambda name: validation_metrics[name][\\"mae_cm\\"])\\n            selection.update(status=\\"trained\\", reason=\\"Selected by validation MAE.\\")\\n        else:\\n            selected_name = \\"train_median\\"\\n            selection.update(\\n                status=\\"baseline_only_insufficient_validation\\",\\n                reason=(f\\"Only {counts[\'validation\']} validation labels; need \\"\\n                        f\\"{min_validation_labels}. Using training median.\\"),\\n            )\\n        selected_models[target] = candidates[selected_name]\\n        selection.update(\\n            selected_model=selected_name,\\n            validation_mae_cm=validation_metrics[selected_name][\\"mae_cm\\"],\\n        )\\n        selection_rows.append(selection)\\n\\n        for part in (\\"validation\\", \\"test\\"):\\n            rows = split.eq(part)\\n            actual = y.loc[rows, target].to_numpy()\\n            for name, estimator in candidates.items():\\n                if part == \\"test\\" and name not in {\\"train_median\\", selected_name}:\\n                    continue\\n                if part == \\"validation\\":\\n                    predicted = validation_predictions[name]\\n                    scores = validation_metrics[name]\\n                else:\\n                    predicted = estimator.predict(X.loc[rows]) if rows.any() else np.empty(0)\\n                    scores = _regression_metrics(actual, predicted)\\n                metric_rows.append({\\n                    \\"target\\": target, \\"model\\": name, \\"split\\": part,\\n                    \\"selected\\": name == selected_name, **scores,\\n                })\\n                prediction_frames.append(pd.DataFrame({\\n                    \\"scan_id\\": X.index[rows], \\"target\\": target, \\"split\\": part,\\n                    \\"actual_cm\\": actual, \\"predicted_cm\\": predicted,\\n                    \\"model\\": name, \\"selected\\": name == selected_name,\\n                }))\\n\\n    selection_table = pd.DataFrame(selection_rows)\\n    if not selected_models:\\n        reasons = \\"; \\".join(f\\"{row[\'target\']}: {row[\'reason\']}\\" for row in selection_rows)\\n        raise ValueError(f\\"No measurement models could be fitted. {reasons}\\")\\n    bundle = {\\n        \\"format_version\\": FORMAT_VERSION,\\n        \\"feature_names\\": X.columns.tolist(),\\n        \\"target_names\\": list(selected_models),\\n        \\"target_units\\": \\"cm\\",\\n        \\"models\\": selected_models,\\n        \\"selection\\": selection_rows,\\n        \\"seed\\": seed,\\n    }\\n    return bundle, pd.DataFrame(metric_rows), pd.concat(prediction_frames, ignore_index=True), selection_table\\n\\n\\ndef predict(bundle: dict, X: pd.DataFrame) -> pd.DataFrame:\\n    \\"\\"\\"Predict centimetres, safely reordering the exact saved feature schema.\\"\\"\\"\\n    if bundle.get(\\"format_version\\") != FORMAT_VERSION:\\n        raise ValueError(\\"Unsupported body measurement model bundle format_version.\\")\\n    X = _numeric_features(X)\\n    expected = bundle[\\"feature_names\\"]\\n    missing = [name for name in expected if name not in X.columns]\\n    additional = [name for name in X.columns if name not in expected]\\n    if missing or additional:\\n        raise ValueError(f\\"Feature schema mismatch; missing={missing}, additional={additional}.\\")\\n    X = X.loc[:, expected]\\n    if not len(X):\\n        return pd.DataFrame(index=X.index, columns=bundle[\\"target_names\\"], dtype=float)\\n    return pd.DataFrame(\\n        {target: bundle[\\"models\\"][target].predict(X) for target in bundle[\\"target_names\\"]},\\n        index=X.index,\\n    )\\n","sha256":"433da514dbd45ec0c72fadf6c5d55b6ac897903694cd115ce10c0a8e9de337ec"},"body_measurements/obj_features.py":{"content":"\\"\\"\\"Build the existing physical geometry feature schema directly from raw OBJs.\\"\\"\\"\\nfrom __future__ import annotations\\n\\nfrom concurrent.futures import ProcessPoolExecutor\\nimport os\\nfrom pathlib import Path\\nimport time\\n\\nimport numpy as np\\nimport pandas as pd\\n\\nfrom scripts.preprocessing.build_scan_geometry_features import FEATURE_NAMES, parse_obj_vertices\\nfrom .data import clean_id\\n\\n\\ndef find_raw_obj_paths(root: str | Path) -> dict[str, Path]:\\n    \\"\\"\\"Index raw scan files, rejecting ambiguous cleaned identifiers.\\"\\"\\"\\n    root = Path(root)\\n    if not root.is_dir():\\n        raise FileNotFoundError(f\\"OBJ root is not a directory: {root}\\")\\n    paths = sorted(path for path in root.rglob(\\"*\\") if path.is_file() and path.suffix.lower() == \\".obj\\")\\n    if not paths:\\n        raise ValueError(f\\"No OBJ files found under {root}\\")\\n    by_id: dict[str, Path] = {}\\n    duplicates = {}\\n    for path in paths:\\n        code = clean_id(path.name)\\n        if code is None:\\n            raise ValueError(f\\"OBJ has no usable scan ID: {path}\\")\\n        if code in by_id:\\n            duplicates.setdefault(code, [by_id[code]]).append(path)\\n        else:\\n            by_id[code] = path\\n    if duplicates:\\n        examples = {code: [str(path) for path in values] for code, values in list(duplicates.items())[:5]}\\n        raise ValueError(f\\"Duplicate cleaned OBJ IDs; select one raw scan per ID: {examples}\\")\\n    return by_id\\n\\n\\ndef _current(path: Path, row: dict | None) -> bool:\\n    if not row or row.get(\\"status\\") != \\"ok\\" or row.get(\\"path\\") != str(path):\\n        return False\\n    stats = path.stat()\\n    try:\\n        return (int(row[\\"source_size\\"]) == stats.st_size\\n                and int(row[\\"source_mtime_ns\\"]) == stats.st_mtime_ns\\n                and np.isfinite([float(row[name]) for name in FEATURE_NAMES]).all())\\n    except (KeyError, TypeError, ValueError):\\n        return False\\n\\n\\ndef _save_partial(path: Path, rows: dict[str, dict]) -> None:\\n    temporary = path.with_suffix(path.suffix + \\".tmp\\")\\n    pd.DataFrame([rows[key] for key in sorted(rows)]).to_csv(temporary, index=False)\\n    os.replace(temporary, path)\\n\\n\\ndef build_obj_features(\\n    obj_root: str | Path,\\n    out_path: str | Path,\\n    *,\\n    workers: int = 2,\\n    checkpoint_every: int = 10,\\n) -> dict:\\n    \\"\\"\\"Stream OBJ vertices without mesh normalization or remeshing.\\n\\n    The sidecar uses the same 14-feature schema as build_scan_geometry_features.\\n    A partial CSV is resumable only when path, byte size, and mtime still match.\\n    \\"\\"\\"\\n    if workers < 1 or checkpoint_every < 1:\\n        raise ValueError(\\"workers and checkpoint_every must be positive integers\\")\\n    out_path = Path(out_path)\\n    if out_path.exists():\\n        raise ValueError(f\\"Output already exists: {out_path}\\")\\n    out_path.parent.mkdir(parents=True, exist_ok=True)\\n    partial = out_path.with_suffix(\\".partial.csv\\")\\n    by_id = find_raw_obj_paths(obj_root)\\n    rows = {}\\n    if partial.exists():\\n        saved = pd.read_csv(partial, dtype={\\"scan_id\\": str}).to_dict(orient=\\"records\\")\\n        if len(saved) != len({row[\\"scan_id\\"] for row in saved}):\\n            raise ValueError(f\\"Duplicate IDs in partial file: {partial}\\")\\n        rows = {row[\\"scan_id\\"]: row for row in saved}\\n    pending = [(code, path) for code, path in sorted(by_id.items()) if not _current(path, rows.get(code))]\\n    print(f\\"[OBJ] {len(by_id)} scans, {len(pending)} to process; partial={partial}\\", flush=True)\\n    started = time.monotonic()\\n    if pending:\\n        with ProcessPoolExecutor(max_workers=workers) as executor:\\n            for done, ((code, path), result) in enumerate(\\n                zip(pending, executor.map(parse_obj_vertices, (str(path) for _, path in pending))), 1\\n            ):\\n                stats = path.stat()\\n                rows[code] = {\\"scan_id\\": code, **result,\\n                              \\"source_size\\": stats.st_size, \\"source_mtime_ns\\": stats.st_mtime_ns}\\n                if done % checkpoint_every == 0 or done == len(pending):\\n                    _save_partial(partial, rows)\\n                    elapsed = max(time.monotonic() - started, 0.001)\\n                    eta_min = (len(pending) - done) * elapsed / done / 60\\n                    print(f\\"[OBJ] {done}/{len(pending)} processed, ETA {eta_min:.1f} min\\", flush=True)\\n    codes = sorted(by_id)\\n    matrix = np.full((len(codes), len(FEATURE_NAMES)), np.nan, dtype=np.float32)\\n    scale_proxy = np.full(len(codes), np.nan, dtype=np.float32)\\n    valid = np.zeros(len(codes), dtype=bool)\\n    source_paths = []\\n    failures = []\\n    for index, code in enumerate(codes):\\n        path = by_id[code]\\n        source_paths.append(str(path))\\n        row = rows[code]\\n        if not _current(path, row):\\n            failures.append({\\"scan_id\\": code, \\"path\\": str(path), \\"error\\": str(row.get(\\"error\\", \\"invalid geometry\\"))})\\n            continue\\n        features = np.asarray([float(row[name]) for name in FEATURE_NAMES], dtype=np.float32)\\n        scale = float(row[\\"scale_proxy\\"])\\n        if not np.isfinite(features).all() or not np.isfinite(scale) or scale <= 0:\\n            failures.append({\\"scan_id\\": code, \\"path\\": str(path), \\"error\\": \\"nonfinite feature or scale\\"})\\n            continue\\n        matrix[index] = features\\n        scale_proxy[index] = scale\\n        valid[index] = True\\n    if not valid.any():\\n        raise ValueError(f\\"No valid OBJ features; inspect {partial}\\")\\n    np.savez_compressed(\\n        out_path,\\n        names=np.asarray(codes, dtype=object), features=matrix,\\n        feature_names=np.asarray(FEATURE_NAMES, dtype=object),\\n        scale_proxy=scale_proxy, valid=valid,\\n        source_paths=np.asarray(source_paths, dtype=object),\\n    )\\n    pd.DataFrame(failures, columns=[\\"scan_id\\", \\"path\\", \\"error\\"]).to_csv(\\n        out_path.with_suffix(\\".failures.csv\\"), index=False,\\n    )\\n    long_index = FEATURE_NAMES.index(\\"bbox_long\\")\\n    long_values = matrix[valid, long_index]\\n    return {\\"obj_root\\": str(Path(obj_root).resolve()), \\"out\\": str(out_path.resolve()),\\n            \\"rows_total\\": len(codes), \\"rows_valid\\": int(valid.sum()),\\n            \\"rows_invalid\\": int((~valid).sum()), \\"rows_reused\\": len(codes) - len(pending),\\n            \\"bbox_long_p05_raw_units\\": float(np.quantile(long_values, 0.05)),\\n            \\"bbox_long_median_raw_units\\": float(np.median(long_values)),\\n            \\"bbox_long_p95_raw_units\\": float(np.quantile(long_values, 0.95))}\\n","sha256":"e0d859863e790793cd37679e73f337b774e479fe08ce6b18c5a3e8261d191698"},"body_measurements/targets.example.json":{"content":"{\\n  \\"description\\": \\"Map confirmed manual-measurement columns and their source units. Null columns disable targets. Predictions are in cm.\\",\\n  \\"targets\\": {\\n    \\"bust_circumference\\": {\\"letter\\": \\"A\\", \\"column\\": null, \\"unit\\": null},\\n    \\"underbust_circumference\\": {\\"letter\\": \\"B\\", \\"column\\": null, \\"unit\\": null},\\n    \\"high_waist_circumference\\": {\\"letter\\": \\"C\\", \\"column\\": null, \\"unit\\": null},\\n    \\"waist_circumference\\": {\\"letter\\": \\"D\\", \\"column\\": null, \\"unit\\": null},\\n    \\"high_hip_circumference\\": {\\"letter\\": \\"E\\", \\"column\\": null, \\"unit\\": null},\\n    \\"hip_circumference\\": {\\"letter\\": \\"F\\", \\"column\\": null, \\"unit\\": null},\\n    \\"buttock_circumference\\": {\\"letter\\": \\"G\\", \\"column\\": null, \\"unit\\": null},\\n    \\"total_thigh_circumference\\": {\\"letter\\": \\"H\\", \\"column\\": null, \\"unit\\": null},\\n    \\"neck_circumference\\": {\\"letter\\": \\"I\\", \\"column\\": null, \\"unit\\": null},\\n    \\"abdominal_circumference\\": {\\"letter\\": \\"J\\", \\"column\\": null, \\"unit\\": null},\\n    \\"max_abdominal_circumference\\": {\\"letter\\": \\"K\\", \\"column\\": null, \\"unit\\": null},\\n    \\"waistband_circumference\\": {\\"letter\\": \\"L\\", \\"column\\": null, \\"unit\\": null},\\n    \\"body_height\\": {\\"letter\\": \\"M\\", \\"column\\": null, \\"unit\\": null},\\n    \\"shoulder_width\\": {\\"letter\\": \\"N\\", \\"column\\": null, \\"unit\\": null},\\n    \\"wrist_circumference\\": {\\"letter\\": \\"O\\", \\"column\\": null, \\"unit\\": null},\\n    \\"left_thigh_circumference\\": {\\"letter\\": \\"P\\", \\"column\\": null, \\"unit\\": null},\\n    \\"right_thigh_circumference\\": {\\"letter\\": \\"Q\\", \\"column\\": null, \\"unit\\": null}\\n  }\\n}\\n","sha256":"608bfc901e304a30011c9287af6698d57ccebfbfd37f20dd81950939420cdca0"},"body_measurements/targets.validation_n1715.json":{"content":"{\\n  \\"description\\": \\"Exact manual measurement headers visible in bodyscan_variables_for_validation_n1715.csv; verify the source export and units before fitting.\\",\\n  \\"targets\\": {\\n    \\"bust_circumference\\": {\\"letter\\": \\"A\\", \\"column\\": \\"bust_chest_girth_cm_3d\\", \\"unit\\": \\"cm\\"},\\n    \\"underbust_circumference\\": {\\"letter\\": \\"B\\", \\"column\\": \\"underbust_circumference_horizontal_cm_3d\\", \\"unit\\": \\"cm\\"},\\n    \\"high_waist_circumference\\": {\\"letter\\": \\"C\\", \\"column\\": \\"high_waist_girth_cm_3d\\", \\"unit\\": \\"cm\\"},\\n    \\"waist_circumference\\": {\\"letter\\": \\"D\\", \\"column\\": \\"waist_girth_cm_3d\\", \\"unit\\": \\"cm\\"},\\n    \\"high_hip_circumference\\": {\\"letter\\": \\"E\\", \\"column\\": \\"high_hip_girth_cm_3d\\", \\"unit\\": \\"cm\\"},\\n    \\"hip_circumference\\": {\\"letter\\": \\"F\\", \\"column\\": \\"hip_girth_cm_3d\\", \\"unit\\": \\"cm\\"},\\n    \\"buttock_circumference\\": {\\"letter\\": \\"G\\", \\"column\\": \\"buttock_girth_cm_3d\\", \\"unit\\": \\"cm\\"},\\n    \\"total_thigh_circumference\\": {\\"letter\\": \\"H\\", \\"column\\": \\"hip_thigh_girth_cm_3d\\", \\"unit\\": \\"cm\\"},\\n    \\"neck_circumference\\": {\\"letter\\": \\"I\\", \\"column\\": \\"mid_neck_girth_cm_3d\\", \\"unit\\": \\"cm\\"},\\n    \\"abdominal_circumference\\": {\\"letter\\": \\"J\\", \\"column\\": \\"belly_circumference_cm_3d\\", \\"unit\\": \\"cm\\"},\\n    \\"max_abdominal_circumference\\": {\\"letter\\": \\"K\\", \\"column\\": \\"maximum_belly_circumference_cm_3d\\", \\"unit\\": \\"cm\\"},\\n    \\"waistband_circumference\\": {\\"letter\\": \\"L\\", \\"column\\": \\"waist_band_cm_3d\\", \\"unit\\": \\"cm\\"},\\n    \\"body_height\\": {\\"letter\\": \\"M\\", \\"column\\": \\"body_height_cm_3d\\", \\"unit\\": \\"cm\\"},\\n    \\"shoulder_width\\": {\\"letter\\": \\"N\\", \\"column\\": \\"cross_shoulder_over_neck_cm_3d\\", \\"unit\\": \\"cm\\"},\\n    \\"wrist_circumference\\": {\\"letter\\": \\"O\\", \\"column\\": \\"wrist_girth_cm_3d\\", \\"unit\\": \\"cm\\"},\\n    \\"left_thigh_circumference\\": {\\"letter\\": \\"P\\", \\"column\\": \\"thigh_girth_left_horizontal_cm_3d\\", \\"unit\\": \\"cm\\"},\\n    \\"right_thigh_circumference\\": {\\"letter\\": \\"Q\\", \\"column\\": \\"thigh_girth_right_horizontal_cm_3d\\", \\"unit\\": \\"cm\\"}\\n  }\\n}\\n","sha256":"cc0e8a09ed63343bcba84b871e06313e588332d1468fad91002e0d5a659bd773"},"body_measurements/requirements.txt":{"content":"numpy>=1.24\\npandas>=2.0\\nscikit-learn>=1.3\\njoblib>=1.3\\n","sha256":"7c3f12fba42757fefa424e0bd5ca28913427500a9fd90b319110b3b2557beb6d"},"scripts/measurements/run_body_measurements_pointcloud.py":{"content":"#!/usr/bin/env python3\\n\\"\\"\\"Physical point-cloud residual regression, with the original cohort held fixed.\\n\\nOnly trusted local joblib/PyTorch checkpoints may be loaded. This experiment is\\nnot guaranteed to improve held-out accuracy. Baseline and residual blend weights\\nare selected using validation labels only; the test partition is report-only.\\n\\"\\"\\"\\nfrom __future__ import annotations\\n\\n# Allow direct execution as well as ``python -m`` from the repository checkout.\\nif __package__ in {None, \\"\\"}:\\n    import sys as _sys\\n    from pathlib import Path as _Path\\n    _sys.path.insert(0, str(_Path(__file__).resolve().parents[2]))\\n\\n\\nimport argparse\\nfrom concurrent.futures import ProcessPoolExecutor\\nfrom datetime import datetime, timezone\\nimport hashlib\\nimport json\\nimport os\\nfrom pathlib import Path\\nimport random\\nimport shutil\\nimport time\\n\\nimport joblib\\nimport numpy as np\\nimport pandas as pd\\nimport torch\\nfrom torch import nn\\nfrom torch.utils.data import DataLoader, Dataset\\n\\nfrom body_measurements.data import align_training, clean_id, load_config, load_features, read_metadata\\nfrom body_measurements.models import predict as baseline_predict\\nfrom scripts.measurements.run_body_measurements import fingerprint, load_split_file, prepare_output, write_json\\n\\n\\nFORMAT = 1\\nMETRES = {\\"m\\": 1.0, \\"cm\\": 0.01, \\"mm\\": 0.001}\\nEXCLUDED_IDS = {\\"RIGDET050925\\"}\\n\\n\\ndef checked_source(spec: dict) -> Path:\\n    path = Path(spec[\\"path\\"])\\n    if not path.is_file():\\n        raise FileNotFoundError(f\\"Original baseline input is missing: {path}\\")\\n    if fingerprint(str(path))[\\"sha256\\"] != spec[\\"sha256\\"]:\\n        raise ValueError(f\\"Baseline input has changed since fitting: {path}\\")\\n    return path\\n\\n\\ndef load_baseline(directory: str | Path):\\n    root = Path(directory)\\n    run = json.loads((root / \\"run.json\\").read_text(encoding=\\"utf-8\\"))\\n    if run.get(\\"status\\") != \\"complete\\" or run.get(\\"scan_units\\") not in METRES:\\n        raise ValueError(\\"Baseline must be complete and declare scan_units m, cm, or mm.\\")\\n    sources = {key: checked_source(run[key]) for key in (\\"features\\", \\"metadata\\", \\"config\\")}\\n    X, _ = load_features(sources[\\"features\\"])\\n    X, y, groups, _ = align_training(X, read_metadata(sources[\\"metadata\\"]),\\n                                     load_config(sources[\\"config\\"]), run[\\"id_col\\"], run.get(\\"participant_col\\"))\\n    manifest = read_metadata(root / \\"splits.csv\\")\\n    wanted = manifest.scan_id.map(clean_id)\\n    if wanted.isna().any() or wanted.duplicated().any():\\n        raise ValueError(\\"Baseline split manifest has empty or duplicate scan IDs.\\")\\n    if set(wanted) != set(X.index):\\n        raise ValueError(\\"Reconstructed cohort differs from the baseline split manifest; refusing cohort changes.\\")\\n    if EXCLUDED_IDS.intersection(wanted):\\n        raise ValueError(\\"Ambiguous excluded scan RIGDET050925 is unexpectedly in the baseline cohort.\\")\\n    X, y, groups = X.loc[wanted], y.loc[wanted], groups.loc[wanted]\\n    splits = load_split_file(str(root / \\"splits.csv\\"), groups)\\n    bundle = joblib.load(root / \\"model.joblib\\")\\n    if bundle[\\"feature_names\\"] != list(X) or bundle[\\"target_names\\"] != list(y):\\n        raise ValueError(\\"Baseline model feature/target schema differs from original cohort.\\")\\n    baseline = baseline_predict(bundle, X)\\n    saved = pd.read_csv(root / \\"evaluation_predictions.csv\\", dtype={\\"scan_id\\": str})\\n    required = {\\"scan_id\\", \\"target\\", \\"split\\", \\"selected\\", \\"actual_cm\\", \\"predicted_cm\\"}\\n    if not required.issubset(saved):\\n        raise ValueError(\\"Baseline evaluation predictions lack the required comparison columns.\\")\\n    saved = saved.loc[saved.selected.astype(str).str.lower().isin([\\"true\\", \\"1\\"])]\\n    if saved.duplicated([\\"scan_id\\", \\"target\\", \\"split\\"]).any():\\n        raise ValueError(\\"Baseline has repeated selected evaluation predictions.\\")\\n    for part in (\\"validation\\", \\"test\\"):\\n        for target in y:\\n            ids = X.index[splits.eq(part)]\\n            rows = saved.loc[saved.split.eq(part) & saved.target.eq(target)].set_index(\\"scan_id\\")\\n            if set(rows.index) != set(ids):\\n                raise ValueError(f\\"Baseline saved evaluation cohort differs for {part}/{target}.\\")\\n            if not np.allclose(rows.loc[ids, \\"actual_cm\\"], y.loc[ids, target], equal_nan=True, rtol=1e-6, atol=1e-5):\\n                raise ValueError(f\\"Baseline saved labels differ for {part}/{target}.\\")\\n            if not np.allclose(rows.loc[ids, \\"predicted_cm\\"], baseline.loc[ids, target], rtol=1e-6, atol=1e-5):\\n                raise ValueError(f\\"Baseline checkpoint no longer reproduces saved predictions for {part}/{target}.\\")\\n    return root, run, sources, X, y, groups, splits, bundle\\n\\n\\ndef farthest_points(points: np.ndarray, count: int) -> np.ndarray:\\n    \\"\\"\\"Deterministic coverage anchors; physical distances are not normalized.\\"\\"\\"\\n    count = min(count, len(points))\\n    indices = np.empty(count, dtype=np.int64)\\n    distance = np.full(len(points), np.inf)\\n    selected = int(np.argmax(np.sum((points - points.mean(0)) ** 2, axis=1)))\\n    for i in range(count):\\n        indices[i] = selected\\n        distance = np.minimum(distance, np.sum((points - points[selected]) ** 2, axis=1))\\n        selected = int(np.argmax(distance))\\n    return indices\\n\\n\\ndef sample_obj(task):\\n    scan_id, path_text, count, anchors1, anchors2, units, seed = task\\n    result = {\\"scan_id\\": scan_id, \\"path\\": path_text, \\"status\\": \\"error\\"}\\n    try:\\n        path = Path(path_text)\\n        before = path.stat()\\n        rng = np.random.default_rng(int.from_bytes(hashlib.sha256(f\\"{seed}:{scan_id}\\".encode()).digest()[:8], \\"little\\"))\\n        sample = np.empty((count, 3), dtype=np.float64)\\n        low, high = np.full(3, np.inf), np.full(3, -np.inf)\\n        vertices, skipped_vertices = 0, 0\\n        with path.open(\\"r\\", encoding=\\"utf-8\\", errors=\\"ignore\\") as stream:\\n            for line in stream:\\n                if len(line) < 3 or line[0] != \\"v\\" or not line[1].isspace():\\n                    continue\\n                fields = line.split(maxsplit=4)\\n                if len(fields) < 4:\\n                    skipped_vertices += 1\\n                    continue\\n                try:\\n                    point = np.asarray([float(value) for value in fields[1:4]])\\n                except ValueError:\\n                    skipped_vertices += 1\\n                    continue\\n                if not np.isfinite(point).all():\\n                    skipped_vertices += 1\\n                    continue\\n                low, high = np.minimum(low, point), np.maximum(high, point)\\n                if vertices < count:\\n                    sample[vertices] = point\\n                else:\\n                    index = int(rng.integers(vertices + 1))\\n                    if index < count:\\n                        sample[index] = point\\n                vertices += 1\\n        if vertices < max(32, anchors1):\\n            raise ValueError(f\\"Only {vertices} vertices; cannot represent requested local geometry\\")\\n        sample = sample[:min(count, vertices)]\\n        if vertices < count:\\n            sample = np.concatenate([sample, sample[rng.integers(len(sample), size=count - len(sample))]])\\n        sample = sample[rng.permutation(count)]\\n        extent = (high - low) * METRES[units]\\n        if not (0.5 <= float(extent.max()) <= 3.0):\\n            raise ValueError(f\\"Physical longest extent {extent.max():.4g} m is implausible; verify declared units\\")\\n        # Translation only: retain body scale, orientation, and left/right.\\n        sample = ((sample - (low + high) / 2) * METRES[units]).astype(np.float32)\\n        a1 = farthest_points(sample, anchors1)\\n        a2 = farthest_points(sample[a1], anchors2)\\n        after = path.stat()\\n        if (before.st_size, before.st_mtime_ns) != (after.st_size, after.st_mtime_ns):\\n            raise ValueError(\\"OBJ changed while it was being read\\")\\n        result.update(status=\\"ok\\", source_size=after.st_size, source_mtime_ns=after.st_mtime_ns,\\n                      vertex_count=vertices, skipped_vertex_records=skipped_vertices,\\n                      extent_m=extent.tolist(), points=sample, a1=a1, a2=a2)\\n    except Exception as exc:\\n        result[\\"error\\"] = str(exc)\\n    return result\\n\\n\\ndef raw_paths(features_path: Path, wanted: list[str], fallback: str | None) -> dict[str, str]:\\n    with np.load(features_path, allow_pickle=True) as sidecar:\\n        if \\"source_paths\\" not in sidecar.files:\\n            raise ValueError(\\"Geometry sidecar needs its source_paths array.\\")\\n        names = [clean_id(value) for value in sidecar[\\"names\\"]]\\n        source_paths = sidecar[\\"source_paths\\"]\\n        if source_paths.shape != (len(names),):\\n            raise ValueError(\\"Sidecar source_paths dimensions disagree.\\")\\n        by_id = dict(zip(names, [str(value) for value in source_paths]))\\n    result = {name: by_id[name] for name in wanted if name in by_id and Path(by_id[name]).is_file()}\\n    missing = set(wanted) - set(result)\\n    if missing and fallback:\\n        candidates = {}\\n        for path in Path(fallback).rglob(\\"*\\"):\\n            if path.is_file() and path.suffix.lower() == \\".obj\\" and clean_id(path.name) in missing:\\n                code = clean_id(path.name)\\n                if code in candidates:\\n                    raise ValueError(f\\"Ambiguous fallback OBJs for requested scan {code}: {candidates[code]}, {path}\\")\\n                candidates[code] = str(path.resolve())\\n        result.update(candidates)\\n    missing = set(wanted) - set(result)\\n    if missing:\\n        raise ValueError(f\\"Missing raw sources for {len(missing)} scans, examples: {sorted(missing)[:10]}\\")\\n    for name, path_text in result.items():\\n        if clean_id(Path(path_text).name) != name:\\n            raise ValueError(f\\"Raw source filename does not agree with scan ID {name}: {path_text}\\")\\n    return result\\n\\n\\ndef build_cache(args):\\n    if args.baseline_run:\\n        _, run, sources, X, _, _, _, _ = load_baseline(args.baseline_run)\\n        features_path, units = sources[\\"features\\"], run[\\"scan_units\\"]\\n        baseline_hash = fingerprint(str(Path(args.baseline_run) / \\"splits.csv\\"))[\\"sha256\\"]\\n    else:\\n        if not args.features or not args.scan_units:\\n            raise ValueError(\\"For new scans, provide --features and --scan-units instead of --baseline-run.\\")\\n        features_path, units = Path(args.features), args.scan_units\\n        X, _ = load_features(features_path)\\n        baseline_hash = None\\n        if EXCLUDED_IDS.intersection(X.index):\\n            raise ValueError(\\"Exclude ambiguous RIGDET050925 from new-scan features explicitly.\\")\\n    output = Path(args.out_dir)\\n    output.mkdir(parents=True, exist_ok=True)\\n    settings = {\\"format_version\\": FORMAT, \\"points\\": args.points, \\"anchors1\\": args.anchors1,\\n                \\"anchors2\\": args.anchors2, \\"seed\\": args.seed, \\"scan_units\\": units,\\n                \\"features\\": fingerprint(str(features_path)), \\"split_sha256\\": baseline_hash,\\n                \\"scan_ids\\": list(X.index), \\"feature_names\\": list(X),\\n                \\"centering\\": \\"full_OBJ_bounding_box_midpoint\\", \\"coordinate_units\\": \\"m\\",\\n                \\"normalization\\": \\"translation_only_no_individual_scale_or_rotation\\",\\n                \\"sampling\\": \\"deterministic_uniform_valid_vertex_reservoir_not_uniform_mesh_surface\\"}\\n    settings_path = output / \\"cache_settings.json\\"\\n    if settings_path.exists():\\n        if json.loads(settings_path.read_text()) != settings:\\n            raise ValueError(\\"Existing cache settings differ. Use a new output directory.\\")\\n    elif any(output.iterdir()):\\n        raise ValueError(\\"Cache output must be new/empty or have matching cache_settings.json.\\")\\n    else:\\n        write_json(settings_path, settings)\\n    paths = raw_paths(features_path, list(X.index), args.obj_root)\\n    parts = output / \\"scans\\"\\n    parts.mkdir(exist_ok=True)\\n    rows, tasks = [], []\\n    for code in X.index:\\n        destination = parts / (hashlib.sha256(code.encode()).hexdigest() + \\".npz\\")\\n        stats = Path(paths[code]).stat()\\n        if destination.exists():\\n            with np.load(destination, allow_pickle=False) as saved:\\n                reusable = (saved[\\"scan_id\\"].item() == code and saved[\\"source_path\\"].item() == paths[code]\\n                            and saved[\\"source_size\\"].item() == stats.st_size\\n                            and saved[\\"source_mtime_ns\\"].item() == stats.st_mtime_ns)\\n            if reusable:\\n                rows.append({\\"scan_id\\": code, \\"status\\": \\"ok\\", \\"reused\\": True})\\n                continue\\n        tasks.append((code, paths[code], args.points, args.anchors1, args.anchors2, units, args.seed))\\n    print(f\\"[CACHE] {len(X)} exact scans; {len(tasks)} to read; {len(rows)} reused\\", flush=True)\\n    started = time.monotonic()\\n    with ProcessPoolExecutor(max_workers=args.workers) as executor:\\n        for done, result in enumerate(executor.map(sample_obj, tasks), 1):\\n            points, a1, a2 = result.pop(\\"points\\", None), result.pop(\\"a1\\", None), result.pop(\\"a2\\", None)\\n            rows.append(result)\\n            if result[\\"status\\"] == \\"ok\\":\\n                code = result[\\"scan_id\\"]\\n                expected_bbox = [f\\"bbox_extent_{axis}\\" for axis in \\"xyz\\"]\\n                if all(name in X for name in expected_bbox):\\n                    expected = X.loc[code, expected_bbox].to_numpy(float)*METRES[units]\\n                    if not np.allclose(result[\\"extent_m\\"], expected, rtol=1e-5, atol=1e-6):\\n                        result.update(status=\\"error\\", error=\\"Raw OBJ bounding box differs from frozen feature sidecar\\")\\n                if \\"log1p_vertex_count\\" in X and not np.isclose(np.log1p(result[\\"vertex_count\\"]), X.loc[code, \\"log1p_vertex_count\\"], rtol=1e-6, atol=1e-6):\\n                    result.update(status=\\"error\\", error=\\"Raw OBJ vertex count differs from frozen feature sidecar\\")\\n            if result[\\"status\\"] == \\"ok\\":\\n                code = result[\\"scan_id\\"]\\n                np.savez_compressed(parts / (hashlib.sha256(code.encode()).hexdigest() + \\".npz\\"),\\n                                    scan_id=code, source_path=result[\\"path\\"], source_size=result[\\"source_size\\"],\\n                                    source_mtime_ns=result[\\"source_mtime_ns\\"], points=points, a1=a1, a2=a2)\\n            if done % 10 == 0 or done == len(tasks):\\n                print(f\\"[CACHE] {done}/{len(tasks)} read, ETA {(len(tasks)-done)*(time.monotonic()-started)/done/60:.1f} min\\", flush=True)\\n                pd.DataFrame(rows).to_csv(output / \\"cache_audit.csv\\", index=False)\\n    pd.DataFrame(rows).to_csv(output / \\"cache_audit.csv\\", index=False)\\n    failures = [row for row in rows if row[\\"status\\"] != \\"ok\\"]\\n    if failures:\\n        raise ValueError(f\\"{len(failures)} OBJ failures; see cache_audit.csv. Cohort was not silently reduced.\\")\\n    arrays, anchor1, anchor2 = [], [], []\\n    for code in X.index:\\n        with np.load(parts / (hashlib.sha256(code.encode()).hexdigest() + \\".npz\\"), allow_pickle=False) as saved:\\n            arrays.append(saved[\\"points\\"])\\n            anchor1.append(saved[\\"a1\\"])\\n            anchor2.append(saved[\\"a2\\"])\\n    temporary = output / \\"point_cache.tmp.npz\\"\\n    np.savez_compressed(temporary, scan_ids=np.asarray(X.index, dtype=str), points=np.stack(arrays),\\n                        a1=np.stack(anchor1), a2=np.stack(anchor2), features=X.to_numpy(np.float32),\\n                        feature_names=np.asarray(X.columns, dtype=str))\\n    os.replace(temporary, output / \\"point_cache.npz\\")\\n    print(f\\"[OUT] {(output / \'point_cache.npz\').resolve()}\\", flush=True)\\n\\n\\ndef gather(values, indices):\\n    return values[torch.arange(values.shape[0], device=values.device).view(-1, *([1] * (indices.ndim - 1))), indices]\\n\\n\\ndef mlp(sizes):\\n    layers = []\\n    for source, destination in zip(sizes[:-1], sizes[1:]):\\n        layers.extend([nn.Linear(source, destination), nn.LayerNorm(destination), nn.GELU()])\\n    return nn.Sequential(*layers)\\n\\n\\nclass MeasurementPointNet(nn.Module):\\n    \\"\\"\\"Two local kNN abstraction stages plus physical geometry and baseline skip.\\"\\"\\"\\n    def __init__(self, features, targets, neighbors1=32, neighbors2=16):\\n        super().__init__()\\n        self.neighbors1, self.neighbors2 = neighbors1, neighbors2\\n        self.stem = mlp([3, 32, 32])\\n        self.local1 = mlp([36, 64, 64])\\n        self.local2 = mlp([132, 128, 128])\\n        self.geometry = mlp([features, 32, 32])\\n        self.head = nn.Sequential(mlp([512 + 64 + 32 + targets, 256, 128]), nn.Dropout(.1), nn.Linear(128, targets))\\n        nn.init.zeros_(self.head[-1].weight)\\n        nn.init.zeros_(self.head[-1].bias)\\n\\n    def abstraction(self, xyz, features, anchor_indices, neighbors, network):\\n        centers = gather(xyz, anchor_indices)\\n        with torch.no_grad():\\n            indices = torch.cdist(centers, xyz).topk(min(neighbors, xyz.shape[1]), largest=False).indices\\n        relative = gather(xyz, indices) - centers[:, :, None]\\n        local = torch.cat([relative, torch.linalg.vector_norm(relative, dim=-1, keepdim=True), gather(features, indices)], -1)\\n        encoded = network(local)\\n        return centers, torch.cat([encoded.max(2).values, encoded.mean(2)], -1)\\n\\n    def forward(self, xyz, geometry, baseline_standardized, a1, a2):\\n        initial = self.stem(xyz)\\n        xyz1, features1 = self.abstraction(xyz, initial, a1, self.neighbors1, self.local1)\\n        _, features2 = self.abstraction(xyz1, features1, a2, self.neighbors2, self.local2)\\n        encoded = torch.cat([features2.max(1).values, features2.mean(1), initial.max(1).values,\\n                             initial.mean(1), self.geometry(geometry), baseline_standardized], -1)\\n        return self.head(encoded)\\n\\n\\nclass ScanDataset(Dataset):\\n    def __init__(self, cache, indices, geometry, baseline, labels):\\n        self.cache, self.indices = cache, np.asarray(indices)\\n        self.geometry, self.baseline, self.labels = geometry, baseline, labels\\n\\n    def __len__(self):\\n        return len(self.indices)\\n\\n    def __getitem__(self, index):\\n        row = self.indices[index]\\n        return tuple(torch.from_numpy(np.array(value, copy=True)) for value in\\n                     (self.cache[\\"points\\"][row], self.geometry[row], self.baseline[row],\\n                      self.cache[\\"a1\\"][row], self.cache[\\"a2\\"][row], self.labels[row]))\\n\\n\\ndef masked_loss(predicted, labels):\\n    mask = torch.isfinite(labels)\\n    if not mask.any():\\n        return predicted.sum()*0\\n    safe = torch.where(mask, labels, predicted.detach())\\n    errors = torch.nn.functional.smooth_l1_loss(predicted, safe, reduction=\\"none\\")\\n    per_target = errors.sum(0) / mask.sum(0).clamp_min(1)\\n    return per_target[mask.any(0)].mean()\\n\\n\\ndef macro_mae(actual, predicted):\\n    return float(np.nanmean(np.nanmean(np.abs(actual - predicted), axis=0)))\\n\\n\\ndef device_for(value):\\n    if value == \\"auto\\":\\n        return torch.device(\\"cuda:0\\" if torch.cuda.is_available() else \\"cpu\\")\\n    try:\\n        device = torch.device(value)\\n    except (RuntimeError, ValueError) as exc:\\n        raise ValueError(\\"Use --device auto, cpu, or cuda:0 (never cuda:-1).\\") from exc\\n    if device.type not in {\\"cpu\\", \\"cuda\\"}:\\n        raise ValueError(\\"Device must be cpu or a valid cuda device.\\")\\n    if device.type == \\"cuda\\" and (not torch.cuda.is_available() or (device.index or 0) >= torch.cuda.device_count()):\\n        raise ValueError(f\\"Requested {device}, but that GPU is unavailable.\\")\\n    return device\\n\\n\\ndef infer(model, loader, device):\\n    model.eval()\\n    rows = []\\n    with torch.no_grad():\\n        for points, geometry, baseline, a1, a2, _ in loader:\\n            rows.append(model(points.to(device), geometry.to(device), baseline.to(device), a1.to(device), a2.to(device)).cpu().numpy())\\n    return np.concatenate(rows)\\n\\n\\ndef read_cache(path):\\n    root = Path(path)\\n    settings = json.loads((root / \\"cache_settings.json\\").read_text())\\n    if settings.get(\\"format_version\\") != FORMAT or settings.get(\\"coordinate_units\\") != \\"m\\":\\n        raise ValueError(\\"Unsupported point-cache format or physical units.\\")\\n    with np.load(root / \\"point_cache.npz\\", allow_pickle=False) as packed:\\n        cache = {key: packed[key] for key in packed.files}\\n    ids = cache[\\"scan_ids\\"].tolist()\\n    if len(ids) != len(set(ids)) or ids != settings[\\"scan_ids\\"]:\\n        raise ValueError(\\"Cache scan IDs are duplicated or differ from cache manifest.\\")\\n    for key in (\\"points\\", \\"features\\"):\\n        if not np.isfinite(cache[key]).all():\\n            raise ValueError(f\\"Cache contains invalid {key}.\\")\\n    if cache[\\"points\\"].shape != (len(ids), settings[\\"points\\"], 3):\\n        raise ValueError(\\"Cached point dimensions differ from declared schema.\\")\\n    if cache[\\"feature_names\\"].tolist() != settings[\\"feature_names\\"] or cache[\\"features\\"].shape != (len(ids), len(settings[\\"feature_names\\"])):\\n        raise ValueError(\\"Cached feature dimensions/names differ from declared schema.\\")\\n    for key, count, limit in ((\\"a1\\", settings[\\"anchors1\\"], settings[\\"points\\"]),\\n                              (\\"a2\\", settings[\\"anchors2\\"], settings[\\"anchors1\\"])):\\n        values = cache[key]\\n        if values.shape != (len(ids), count) or not np.issubdtype(values.dtype, np.integer) or (values < 0).any() or (values >= limit).any():\\n            raise ValueError(f\\"Invalid point-anchor indices: {key}\\")\\n    return cache, settings\\n\\n\\ndef metrics_table(actual, predicted, names, groups, baseline, bootstrap, seed):\\n    rng = np.random.default_rng(seed)\\n    rows = []\\n    for j, target in enumerate(names):\\n        valid = np.isfinite(actual[:, j])\\n        truth, prediction, old = actual[valid, j], predicted[valid, j], baseline[valid, j]\\n        people = np.asarray(groups)[valid]\\n        error, old_error = np.abs(truth-prediction), np.abs(truth-old)\\n        unique = np.unique(people)\\n        # Cluster bootstrap participants, retaining every scan from each sampled person.\\n        mapping = {person: np.flatnonzero(people == person) for person in unique}\\n        boot = []\\n        for _ in range(bootstrap):\\n            indices = np.concatenate([mapping[person] for person in rng.choice(unique, len(unique), replace=True)])\\n            mae = float(error[indices].mean())\\n            boot.append([mae, float((error[indices]-old_error[indices]).mean()), 100*mae/float(truth[indices].mean())])\\n        interval = np.quantile(boot, [.025, .975], axis=0) if boot else np.full((2, 3), np.nan)\\n        baseline_mae = float(old_error.mean())\\n        mae = float(error.mean())\\n        denominator = float(np.sum((truth-truth.mean())**2))\\n        rows.append({\\"target\\": target, \\"n\\": len(truth), \\"participants\\": len(unique),\\n                     \\"mean_measured_cm\\": float(truth.mean()), \\"mae_cm\\": mae,\\n                     \\"mae_ci95_low_cm\\": interval[0, 0], \\"mae_ci95_high_cm\\": interval[1, 0],\\n                     \\"mae_pct_of_mean\\": 100*mae/float(truth.mean()),\\n                     \\"mae_pct_ci95_low\\": interval[0, 2], \\"mae_pct_ci95_high\\": interval[1, 2],\\n                     \\"baseline_mae_cm\\": baseline_mae, \\"delta_mae_cm\\": mae-baseline_mae,\\n                     \\"delta_ci95_low_cm\\": interval[0, 1], \\"delta_ci95_high_cm\\": interval[1, 1],\\n                     \\"improvement_pct\\": 100*(baseline_mae-mae)/baseline_mae if baseline_mae else np.nan,\\n                     \\"rmse_cm\\": float(np.sqrt(np.mean((truth-prediction)**2))),\\n                     \\"r2\\": 1-float(np.sum((truth-prediction)**2))/denominator if denominator else np.nan,\\n                     \\"within_1_cm\\": float((error <= 1).mean()), \\"within_2_cm\\": float((error <= 2).mean())})\\n    return pd.DataFrame(rows)\\n\\n\\ndef train(args):\\n    root, run, sources, X, y, groups, splits, bundle = load_baseline(args.baseline_run)\\n    cache, cache_settings = read_cache(args.cache)\\n    if cache[\\"scan_ids\\"].tolist() != list(X.index) or cache[\\"feature_names\\"].tolist() != list(X):\\n        raise ValueError(\\"Cache cohort/order/schema differs from exact baseline.\\")\\n    if cache_settings[\\"features\\"] != fingerprint(str(sources[\\"features\\"])) or cache_settings[\\"split_sha256\\"] != fingerprint(str(root / \\"splits.csv\\"))[\\"sha256\\"]:\\n        raise ValueError(\\"Cache feature provenance or split fingerprint differs from baseline.\\")\\n    if cache_settings[\\"scan_units\\"] != run[\\"scan_units\\"] or not np.allclose(cache[\\"features\\"], X.to_numpy(), rtol=1e-6, atol=1e-6):\\n        raise ValueError(\\"Cached geometry or units differ from baseline inputs.\\")\\n    torch.set_num_threads(getattr(args, \\"threads\\", 2))\\n    torch.manual_seed(args.seed)\\n    np.random.seed(args.seed)\\n    random.seed(args.seed)\\n    if torch.cuda.is_available():\\n        torch.cuda.manual_seed_all(args.seed)\\n    device = device_for(args.device)\\n    masks = {part: splits.eq(part).to_numpy() for part in (\\"train\\", \\"validation\\", \\"test\\")}\\n    actual = y.to_numpy(np.float32)\\n    for part in masks:\\n        if (np.isfinite(actual[masks[part]]).sum(0) < (10 if part == \\"train\\" else 3)).any():\\n            raise ValueError(f\\"Each target needs >=10 train and >=3 held-out labels; insufficient {part} coverage.\\")\\n    # Fit statistics exclusively on training scans, never validation or test.\\n    training = actual[masks[\\"train\\"]]\\n    target_mean = np.nanmean(training, 0)\\n    target_std = np.maximum(np.nanstd(training, 0), .1)\\n    geom_mean = X.to_numpy()[masks[\\"train\\"]].mean(0)\\n    geom_std = np.maximum(X.to_numpy()[masks[\\"train\\"]].std(0), 1e-6)\\n    geometry = ((X.to_numpy()-geom_mean)/geom_std).astype(np.float32)\\n    baseline = baseline_predict(bundle, X).to_numpy(np.float32)\\n    standardized_base = ((baseline-target_mean)/target_std).astype(np.float32)\\n    residual_labels = ((actual-baseline)/target_std).astype(np.float32)\\n    loaders = {}\\n    for part, mask in masks.items():\\n        data = ScanDataset(cache, np.flatnonzero(mask), geometry, standardized_base, residual_labels)\\n        loaders[part] = DataLoader(data, batch_size=args.batch_size, shuffle=part == \\"train\\", num_workers=0)\\n    model = MeasurementPointNet(X.shape[1], y.shape[1], args.neighbors1, args.neighbors2).to(device)\\n    optimizer = torch.optim.AdamW(model.parameters(), lr=args.learning_rate, weight_decay=args.weight_decay)\\n    scheduler = torch.optim.lr_scheduler.ReduceLROnPlateau(optimizer, mode=\\"min\\", factor=.5, patience=8)\\n    output = prepare_output(args.out_dir)\\n    shutil.copy2(root / \\"model.joblib\\", output / \\"baseline_model.joblib\\")\\n    shutil.copy2(root / \\"splits.csv\\", output / \\"splits.csv\\")\\n    settings = {\\"format_version\\": FORMAT, \\"created_utc\\": datetime.now(timezone.utc).isoformat(),\\n                \\"status\\": \\"training\\", \\"baseline_run\\": str(root.resolve()), \\"baseline_run_file\\": fingerprint(str(root / \\"run.json\\")),\\n                \\"baseline_model\\": fingerprint(str(root / \\"model.joblib\\")), \\"split_source\\": fingerprint(str(root / \\"splits.csv\\")),\\n                \\"baseline_inputs\\": {key: fingerprint(str(path)) for key, path in sources.items()},\\n                \\"feature_names\\": list(X), \\"target_names\\": list(y), \\"scan_units\\": run[\\"scan_units\\"],\\n                \\"geometry_mean\\": geom_mean.tolist(), \\"geometry_std\\": geom_std.tolist(),\\n                \\"target_mean_cm\\": target_mean.tolist(), \\"target_std_cm\\": target_std.tolist(),\\n                \\"cache_settings\\": cache_settings, \\"training_options\\": vars(args),\\n                \\"architecture\\": \\"local_knn_residual_pointnet_two_stages_with_frozen_baseline\\",\\n                \\"no_augmentation\\": \\"No rotations, flips, scale changes, PCA alignment, or per-scan radius normalization.\\",\\n                \\"selection\\": \\"Validation macro MAE checkpoint, then per-target validation blend in [0,.25,.5,1]. Test report only.\\",\\n                \\"versions\\": {\\"torch\\": torch.__version__, \\"numpy\\": np.__version__, \\"pandas\\": pd.__version__}}\\n    settings[\\"training_options\\"].pop(\\"function\\", None)\\n    write_json(output / \\"run.json\\", settings)\\n    best = macro_mae(actual[masks[\\"validation\\"]], baseline[masks[\\"validation\\"]])\\n    best_epoch, stale = 0, 0\\n    history = [{\\"epoch\\": 0, \\"validation_macro_mae_cm\\": best, \\"train_loss\\": None}]\\n    def save_checkpoint(epoch, metric):\\n        torch.save({\\"format_version\\": FORMAT, \\"state_dict\\": model.state_dict(), \\"epoch\\": epoch,\\n                    \\"validation_macro_mae_cm\\": metric, \\"settings\\": settings}, output / \\"best_model.pt\\")\\n    save_checkpoint(0, best)\\n    print(f\\"[TRAIN] {len(X)} scans, {y.shape[1]} targets, device={device}, parameters={sum(p.numel() for p in model.parameters()):,}\\", flush=True)\\n    print(f\\"[BASELINE] validation macro MAE={best:.4f} cm; epoch 0 is a valid saved competitor\\", flush=True)\\n    try:\\n        for epoch in range(1, args.epochs+1):\\n            started = time.monotonic()\\n            model.train()\\n            losses = []\\n            for step, (points, geom, old, a1, a2, labels) in enumerate(loaders[\\"train\\"], 1):\\n                optimizer.zero_grad(set_to_none=True)\\n                predicted = model(points.to(device), geom.to(device), old.to(device), a1.to(device), a2.to(device))\\n                loss = masked_loss(predicted, labels.to(device))\\n                if not torch.isfinite(loss):\\n                    raise ValueError(\\"Nonfinite training loss\\")\\n                loss.backward()\\n                nn.utils.clip_grad_norm_(model.parameters(), 5)\\n                optimizer.step()\\n                losses.append(float(loss.detach().cpu()))\\n                if step % args.log_every == 0:\\n                    print(f\\"[TRAIN] epoch {epoch} batch {step}/{len(loaders[\'train\'])}, loss={np.mean(losses):.5f}\\", flush=True)\\n            correction = infer(model, loaders[\\"validation\\"], device)*target_std\\n            validation_mae = macro_mae(actual[masks[\\"validation\\"]], baseline[masks[\\"validation\\"]]+correction)\\n            scheduler.step(validation_mae)\\n            improved = validation_mae < best-1e-5\\n            if improved:\\n                best, best_epoch, stale = validation_mae, epoch, 0\\n                save_checkpoint(epoch, best)\\n            else:\\n                stale += 1\\n            history.append({\\"epoch\\": epoch, \\"validation_macro_mae_cm\\": validation_mae, \\"train_loss\\": float(np.mean(losses))})\\n            pd.DataFrame(history).to_csv(output / \\"training_history.csv\\", index=False)\\n            print(f\\"[EPOCH] {epoch}/{args.epochs}, validation MAE={validation_mae:.4f} cm, best={best:.4f} (epoch {best_epoch}), {time.monotonic()-started:.1f}s\\", flush=True)\\n            if stale >= args.patience:\\n                print(f\\"[STOP] No validation improvement for {args.patience} epochs\\", flush=True)\\n                break\\n        checkpoint = torch.load(output / \\"best_model.pt\\", map_location=device, weights_only=False)\\n        model.load_state_dict(checkpoint[\\"state_dict\\"])\\n        validation_correction = infer(model, loaders[\\"validation\\"], device)*target_std\\n        blend_weights, selected = [], []\\n        for j, target in enumerate(y):\\n            scores = {weight: float(np.nanmean(np.abs(actual[masks[\\"validation\\"], j] - (baseline[masks[\\"validation\\"], j]+weight*validation_correction[:, j]))))\\n                      for weight in (0., .25, .5, 1.)}\\n            weight = min(scores, key=scores.get)\\n            blend_weights.append(weight)\\n            selected.append({\\"target\\": target, \\"residual_weight\\": weight, \\"validation_mae_cm\\": scores[weight],\\n                             \\"baseline_validation_mae_cm\\": scores[0.], \\"checkpoint_epoch\\": best_epoch})\\n        pd.DataFrame(selected).to_csv(output / \\"model_selection.csv\\", index=False)\\n        checkpoint[\\"blend_weights\\"] = blend_weights\\n        # Test is read only after checkpoint and per-target blend selection are frozen.\\n        tables = []\\n        for part in (\\"validation\\", \\"test\\"):\\n            correction = validation_correction if part == \\"validation\\" else infer(model, loaders[part], device)*target_std\\n            prediction = baseline[masks[part]]+correction*np.asarray(blend_weights)\\n            idx = np.flatnonzero(masks[part])\\n            frame = pd.DataFrame({\\"scan_id\\": np.repeat(np.asarray(X.index)[idx], len(y.columns)),\\n                                  \\"participant_id\\": np.repeat(groups.to_numpy()[idx], len(y.columns)),\\n                                  \\"target\\": np.tile(y.columns, len(idx)), \\"split\\": part,\\n                                  \\"actual_cm\\": actual[idx].ravel(), \\"predicted_cm\\": prediction.ravel(),\\n                                  \\"baseline_predicted_cm\\": baseline[idx].ravel(),\\n                                  \\"full_residual_predicted_cm\\": (baseline[idx]+correction).ravel(),\\n                                  \\"model\\": \\"validation_selected_pointcloud_residual\\", \\"selected\\": True})\\n            tables.append(frame)\\n            metrics_table(actual[idx], prediction, list(y), groups.to_numpy()[idx], baseline[idx],\\n                          args.bootstrap if part == \\"test\\" else 0, args.seed).to_csv(output / f\\"{part}_metrics.csv\\", index=False)\\n        pd.concat(tables, ignore_index=True).to_csv(output / \\"evaluation_predictions.csv\\", index=False)\\n        settings.update(status=\\"complete\\", best_epoch=best_epoch, best_validation_macro_mae_cm=best,\\n                        residual_weights=dict(zip(y.columns, blend_weights)),\\n                        test_intervals=\\"95% participant cluster bootstrap; same sampled people used in paired MAE difference. Fixed fitted model only.\\")\\n        checkpoint[\\"settings\\"] = dict(settings)\\n        torch.save(checkpoint, output / \\"best_model.pt\\")\\n        settings[\\"checkpoint\\"] = fingerprint(str(output / \\"best_model.pt\\"))\\n        write_json(output / \\"run.json\\", settings)\\n        print(pd.read_csv(output / \\"test_metrics.csv\\")[[\\"target\\", \\"n\\", \\"mae_cm\\", \\"mae_pct_of_mean\\", \\"baseline_mae_cm\\", \\"delta_mae_cm\\"]].round(3).to_string(index=False))\\n        print(f\\"[OUT] {output.resolve()}\\", flush=True)\\n    except Exception as exc:\\n        settings.update(status=\\"failed\\", error=str(exc))\\n        write_json(output / \\"run.json\\", settings)\\n        raise\\n\\n\\ndef predict_new(args):\\n    root = Path(args.model_run)\\n    torch.set_num_threads(getattr(args, \\"threads\\", 2))\\n    device = device_for(args.device)\\n    run = json.loads((root / \\"run.json\\").read_text())\\n    if run.get(\\"status\\") != \\"complete\\" or fingerprint(str(root / \\"best_model.pt\\"))[\\"sha256\\"] != run.get(\\"checkpoint\\", {}).get(\\"sha256\\"):\\n        raise ValueError(\\"Model run is incomplete/failed or checkpoint fingerprint differs from final manifest.\\")\\n    checkpoint = torch.load(root / \\"best_model.pt\\", map_location=device, weights_only=False)\\n    if checkpoint.get(\\"format_version\\") != FORMAT or checkpoint.get(\\"settings\\", {}).get(\\"status\\") != \\"complete\\":\\n        raise ValueError(\\"Checkpoint is not a completed measurement point-cloud experiment.\\")\\n    settings = checkpoint[\\"settings\\"]\\n    cache, current = read_cache(args.cache)\\n    expected = settings[\\"cache_settings\\"]\\n    for key in (\\"points\\", \\"anchors1\\", \\"anchors2\\", \\"seed\\", \\"scan_units\\", \\"feature_names\\", \\"centering\\", \\"normalization\\"):\\n        if current[key] != expected[key]:\\n            raise ValueError(f\\"New scan cache differs from training schema: {key}\\")\\n    X = pd.DataFrame(cache[\\"features\\"], index=cache[\\"scan_ids\\"], columns=cache[\\"feature_names\\"])\\n    baseline_path = root / \\"baseline_model.joblib\\"\\n    if fingerprint(str(baseline_path))[\\"sha256\\"] != settings[\\"baseline_model\\"][\\"sha256\\"]:\\n        raise ValueError(\\"Deployed baseline model fingerprint differs from training.\\")\\n    baseline = baseline_predict(joblib.load(baseline_path), X).to_numpy(np.float32)\\n    mean, std = np.asarray(settings[\\"target_mean_cm\\"]), np.asarray(settings[\\"target_std_cm\\"])\\n    geometry = ((X.to_numpy()-settings[\\"geometry_mean\\"])/settings[\\"geometry_std\\"]).astype(np.float32)\\n    dataset = ScanDataset(cache, np.arange(len(X)), geometry, ((baseline-mean)/std).astype(np.float32), np.zeros_like(baseline))\\n    options = settings[\\"training_options\\"]\\n    model = MeasurementPointNet(X.shape[1], baseline.shape[1], options[\\"neighbors1\\"], options[\\"neighbors2\\"]).to(device)\\n    model.load_state_dict(checkpoint[\\"state_dict\\"])\\n    correction = infer(model, DataLoader(dataset, batch_size=args.batch_size, shuffle=False, num_workers=0), device)*std\\n    prediction = baseline+correction*np.asarray(checkpoint[\\"blend_weights\\"])\\n    if not np.isfinite(prediction).all():\\n        raise ValueError(\\"Nonfinite new scan predictions\\")\\n    destination = Path(args.output)\\n    if destination.exists():\\n        raise ValueError(\\"Prediction output exists; choose a new filename.\\")\\n    destination.parent.mkdir(parents=True, exist_ok=True)\\n    pd.DataFrame(prediction, index=pd.Index(X.index, name=\\"scan_id\\"), columns=settings[\\"target_names\\"]).to_csv(destination)\\n    print(f\\"[OUT] {destination.resolve()} (all measurement columns in cm)\\", flush=True)\\n\\n\\ndef positive(value):\\n    value = int(value)\\n    if value < 1:\\n        raise argparse.ArgumentTypeError(\\"Must be >=1\\")\\n    return value\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser(description=__doc__)\\n    sub = parser.add_subparsers(dest=\\"command\\", required=True)\\n    cache = sub.add_parser(\\"build-cache\\", help=\\"Read exact baseline raw OBJ cohort, or a new-scan feature sidecar\\")\\n    source = cache.add_mutually_exclusive_group(required=True)\\n    source.add_argument(\\"--baseline-run\\")\\n    source.add_argument(\\"--features\\")\\n    cache.add_argument(\\"--scan-units\\", choices=METRES)\\n    cache.add_argument(\\"--obj-root\\", help=\\"Fallback only if saved raw source paths no longer exist\\")\\n    cache.add_argument(\\"--out-dir\\", required=True)\\n    cache.add_argument(\\"--points\\", type=positive, default=2048)\\n    cache.add_argument(\\"--anchors1\\", type=positive, default=128)\\n    cache.add_argument(\\"--anchors2\\", type=positive, default=32)\\n    cache.add_argument(\\"--workers\\", type=positive, default=2)\\n    cache.add_argument(\\"--seed\\", type=int, default=42)\\n    cache.set_defaults(function=build_cache)\\n    fit = sub.add_parser(\\"train\\", help=\\"Validation-selected residual experiment; frozen original participant splits\\")\\n    fit.add_argument(\\"--baseline-run\\", required=True)\\n    fit.add_argument(\\"--cache\\", required=True)\\n    fit.add_argument(\\"--out-dir\\", required=True)\\n    fit.add_argument(\\"--device\\", default=\\"auto\\")\\n    fit.add_argument(\\"--epochs\\", type=positive, default=150)\\n    fit.add_argument(\\"--patience\\", type=positive, default=25)\\n    fit.add_argument(\\"--batch-size\\", type=positive, default=8)\\n    fit.add_argument(\\"--threads\\", type=positive, default=2)\\n    fit.add_argument(\\"--neighbors1\\", type=positive, default=32)\\n    fit.add_argument(\\"--neighbors2\\", type=positive, default=16)\\n    fit.add_argument(\\"--learning-rate\\", type=float, default=.0005)\\n    fit.add_argument(\\"--weight-decay\\", type=float, default=.0001)\\n    fit.add_argument(\\"--bootstrap\\", type=int, default=2000)\\n    fit.add_argument(\\"--seed\\", type=int, default=42)\\n    fit.add_argument(\\"--log-every\\", type=positive, default=25)\\n    fit.set_defaults(function=train)\\n    prediction = sub.add_parser(\\"predict\\", help=\\"Apply the saved baseline plus validation-selected residual blend\\")\\n    prediction.add_argument(\\"--model-run\\", required=True)\\n    prediction.add_argument(\\"--cache\\", required=True)\\n    prediction.add_argument(\\"--output\\", required=True)\\n    prediction.add_argument(\\"--device\\", default=\\"auto\\")\\n    prediction.add_argument(\\"--batch-size\\", type=positive, default=8)\\n    prediction.add_argument(\\"--threads\\", type=positive, default=2)\\n    prediction.set_defaults(function=predict_new)\\n    args = parser.parse_args()\\n    if args.command == \\"build-cache\\" and not (args.anchors2 <= args.anchors1 <= args.points):\\n        parser.error(\\"Require anchors2 <= anchors1 <= points\\")\\n    if args.command == \\"train\\" and (args.bootstrap < 0 or args.learning_rate <= 0 or args.weight_decay < 0):\\n        parser.error(\\"bootstrap/weight-decay must be nonnegative and learning-rate positive\\")\\n    args.function(args)\\n\\n\\nif __name__ == \\"__main__\\":\\n    main()\\n","sha256":"cf057e95280899adcdb5bb68ac1534592ebab2c0e61faf02ab976ce368ac89a4"},"scripts/training/__init__.py":{"content":"\\"\\"\\"Training command entry points.\\"\\"\\"\\n","sha256":"c1576fa340ffc02606653e18e8036c5e8860f402c26bc754862e75e85b00982a"},"scripts/training/train_body_measurements_expanded.py":{"content":"#!/usr/bin/env python3\\n\\"\\"\\"Expand the labelled scan cohort using the existing measurement trainers.\\"\\"\\"\\n\\n# Allow direct execution as well as ``python -m`` from the repository checkout.\\nif __package__ in {None, \\"\\"}:\\n    import sys as _sys\\n    from pathlib import Path as _Path\\n    _sys.path.insert(0, str(_Path(__file__).resolve().parents[2]))\\n\\nfrom scripts._paths import REPO_ROOT, script_path\\n\\nimport argparse\\nimport json\\nfrom pathlib import Path\\nimport subprocess\\nimport sys\\n\\nimport numpy as np\\nimport pandas as pd\\n\\nfrom body_measurements.data import align_training, clean_id, load_features, read_metadata\\nfrom scripts.measurements.run_body_measurements_pointcloud import EXCLUDED_IDS, METRES, load_baseline, raw_paths\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser(description=__doc__)\\n    parser.add_argument(\\"--obj-root\\", required=True)\\n    parser.add_argument(\\"--out-dir\\", required=True)\\n    parser.add_argument(\\"--old-baseline\\", default=\\"measurement_runs/n2894_baseline_01\\")\\n    parser.add_argument(\\"--epochs\\", type=int, default=150)\\n    parser.add_argument(\\"--patience\\", type=int, default=25)\\n    parser.add_argument(\\"--points\\", type=int, default=2048)\\n    parser.add_argument(\\"--bootstrap\\", type=int, default=2000)\\n    parser.add_argument(\\"--device\\", default=\\"auto\\")\\n    args = parser.parse_args()\\n    root, output = Path(args.obj_root).resolve(), Path(args.out_dir).resolve()\\n    if not root.is_dir():\\n        raise ValueError(f\\"Scan folder is missing: {root}\\")\\n    if output.exists():\\n        raise ValueError(f\\"Use a new output folder; already exists: {output}\\")\\n    if args.epochs < 1 or args.patience < 1 or args.points < 128 or args.bootstrap < 0:\\n        raise ValueError(\\"epochs/patience must be positive, points >=128, bootstrap >=0\\")\\n    _, run, sources, old_X, _, old_groups, old_splits, _ = load_baseline(args.old_baseline)\\n    metadata = read_metadata(sources[\\"metadata\\"])\\n    targets = run[\\"targets\\"]\\n    inventory = pd.DataFrame(\\n        [(clean_id(p.name), str(p)) for p in sorted(root.rglob(\\"*\\"))\\n         if p.is_file() and p.suffix.lower() == \\".obj\\"], columns=[\\"scan_id\\", \\"path\\"])\\n    if inventory.empty:\\n        raise ValueError(f\\"No OBJ files found under {root}\\")\\n    inventory[\\"ambiguous_id\\"] = inventory.scan_id.duplicated(keep=False)\\n    unique = inventory.loc[inventory.scan_id.notna() & ~inventory.ambiguous_id\\n                           & ~inventory.scan_id.isin(EXCLUDED_IDS)]\\n    paths = dict(zip(unique.scan_id, unique.path))\\n    # Preserve the actual scan sources used in the old evaluation, including\\n    # scans whose other exports are duplicated in the new collection.\\n    paths.update(raw_paths(sources[\\"features\\"], list(old_X.index), None))\\n    stub = pd.DataFrame({\\"inventory_only\\": 0.0}, index=pd.Index(sorted(paths), name=\\"scan_id\\"))\\n    selected, _, _, _ = align_training(stub, metadata, targets, run[\\"id_col\\"], run.get(\\"participant_col\\"))\\n    output.mkdir(parents=True)\\n    inventory.to_csv(output / \\"obj_inventory.csv\\", index=False)\\n    view = output / \\"labelled_obj_sources\\"\\n    view.mkdir()\\n    for code in selected.index:\\n        (view / f\\"{code}.obj\\").symlink_to(Path(paths[code]).resolve())\\n    pd.DataFrame({\\"scan_id\\": selected.index,\\n                  \\"source_path\\": [str(Path(paths[c]).resolve()) for c in selected.index],\\n                  \\"original_cohort\\": selected.index.isin(old_X.index)}).to_csv(\\n                      output / \\"source_selection.csv\\", index=False)\\n    print(f\\"[SELECT] {len(inventory)} OBJ files; {len(selected)} labelled scan IDs; \\"\\n          f\\"{len(old_X)} original scan sources preserved\\", flush=True)\\n\\n    code_root = REPO_ROOT\\n    def execute(script, *arguments):\\n        command = [sys.executable, \\"-u\\", str(script_path(script)), *map(str, arguments)]\\n        print(\\"[RUN] \\" + \\" \\".join(command), flush=True)\\n        subprocess.run(command, check=True)\\n\\n    execute(\\"run_body_measurements.py\\", \\"build-features\\", \\"--obj-root\\", view,\\n            \\"--workers\\", 2, \\"--out-dir\\", output / \\"features\\")\\n    features = output / \\"features\\" / \\"scan_geometry_features.npz\\"\\n    X, feature_audit = load_features(features)\\n    X, y, groups, alignment = align_training(X, metadata, targets, run[\\"id_col\\"], run.get(\\"participant_col\\"))\\n    missing = old_X.index.difference(X.index)\\n    if len(missing):\\n        raise ValueError(f\\"Original cohort lost scans; training stopped: {list(missing[:10])}\\")\\n    if list(X.columns) != list(old_X.columns) or not np.allclose(\\n            X.loc[old_X.index].to_numpy(), old_X.to_numpy(), rtol=1e-5, atol=1e-6):\\n        raise ValueError(\\"Original scan geometry changed; training stopped before altering the comparison\\")\\n    if not groups.loc[old_groups.index].equals(old_groups):\\n        raise ValueError(\\"Original participant identities changed\\")\\n    added = ~X.index.isin(old_X.index)\\n    axes = [f\\"bbox_extent_{axis}\\" for axis in \\"xyz\\"]\\n    expected_axis = old_X[axes].idxmax(axis=1).mode().iat[0]\\n    size_m = X.bbox_long * METRES[run[\\"scan_units\\"]]\\n    unusual = added & (~size_m.between(0.8, 3.0) | X[axes].idxmax(axis=1).ne(expected_axis))\\n    if unusual.any():\\n        X.loc[unusual, axes + [\\"bbox_long\\"]].to_csv(output / \\"scan_format_review.csv\\")\\n        raise ValueError(\\"Some added scans have unexpected physical size or upright axis. \\"\\n                         \\"Training stopped; inspect scan_format_review.csv. No automatic rescaling/rotation.\\")\\n    mapping = dict(zip(old_groups, old_splits))\\n    new_people = sorted(set(groups) - set(mapping))\\n    shuffled = np.random.default_rng(42).permutation(new_people)\\n    mapping.update({person: \\"validation\\" if i % 5 == 0 else \\"train\\" for i, person in enumerate(shuffled)})\\n    splits = groups.map(mapping)\\n    if not splits.loc[old_splits.index].equals(old_splits.rename(splits.name)):\\n        raise ValueError(\\"Original split assignments changed\\")\\n    manifest = pd.DataFrame({\\"scan_id\\": X.index, \\"participant_id\\": groups.to_numpy(), \\"split\\": splits.to_numpy()})\\n    split_file = output / \\"expanded_splits.csv\\"\\n    manifest.to_csv(split_file, index=False)\\n    (output / \\"expansion_audit.json\\").write_text(json.dumps({\\n        \\"old_baseline\\": str(Path(args.old_baseline).resolve()), \\"scan_root\\": str(root),\\n        \\"selected_scan_ids\\": len(selected), \\"features\\": feature_audit, \\"alignment\\": alignment,\\n        \\"split_counts\\": splits.value_counts().to_dict(), \\"new_participants\\": len(new_people),\\n        \\"original_assignments_preserved\\": True, \\"scan_units\\": run[\\"scan_units\\"],\\n        \\"format_check\\": \\"Broad size and dominant-axis screen only; cannot verify pose or left/right orientation\\"\\n    }, indent=2) + \\"\\\\n\\")\\n    print(\\"[COHORT]\\", len(X), \\"valid labelled scans; splits:\\", splits.value_counts().to_dict(), flush=True)\\n    common = [\\"--metadata\\", sources[\\"metadata\\"], \\"--id-col\\", run[\\"id_col\\"],\\n              \\"--config\\", sources[\\"config\\"], \\"--features\\", features]\\n    if run.get(\\"participant_col\\"):\\n        common += [\\"--participant-col\\", run[\\"participant_col\\"]]\\n    baseline, cache, model = output / \\"baseline\\", output / \\"point_cache_2048\\", output / \\"pointcloud\\"\\n    execute(\\"run_body_measurements.py\\", \\"train\\", *common, \\"--scan-units\\", run[\\"scan_units\\"],\\n            \\"--splits\\", split_file, \\"--seed\\", 42, \\"--n-jobs\\", 2, \\"--out-dir\\", baseline)\\n    execute(\\"run_body_measurements_pointcloud.py\\", \\"build-cache\\", \\"--baseline-run\\", baseline,\\n            \\"--points\\", args.points, \\"--workers\\", 2, \\"--out-dir\\", cache)\\n    execute(\\"run_body_measurements_pointcloud.py\\", \\"train\\", \\"--baseline-run\\", baseline,\\n            \\"--cache\\", cache, \\"--device\\", args.device, \\"--batch-size\\", 8, \\"--threads\\", 2,\\n            \\"--epochs\\", args.epochs, \\"--patience\\", args.patience, \\"--bootstrap\\", args.bootstrap,\\n            \\"--out-dir\\", model)\\n    print(\\"[DONE] New model:\\", model, flush=True)\\n    print(\\"[RESULTS]\\", model / \\"test_metrics.csv\\", flush=True)\\n\\n\\nif __name__ == \\"__main__\\":\\n    main()\\n","sha256":"b81c547067e16753b6277118c5419b2c18c52417824247062d7f1d12a6ce3780"}}')

root = Path.cwd().resolve()
for name, item in payload.items():
    destination = root / name
    if not destination.resolve().is_relative_to(root):
        raise SystemExit(f"Unsafe installer path: {name}")
    if hashlib.sha256(item["content"].encode("utf-8")).hexdigest() != item["sha256"]:
        raise SystemExit(f"Incomplete installer copy: {name}")
    if name.endswith(".py"):
        compile(item["content"], name, "exec")
stamp = datetime.now().strftime("%Y%m%d_%H%M%S_%f")
for name, item in payload.items():
    destination = root / name
    destination.parent.mkdir(parents=True, exist_ok=True)
    if destination.exists():
        shutil.copy2(destination, destination.with_name(destination.name + ".backup_" + stamp))
    temporary = destination.with_name(destination.name + ".incoming")
    temporary.write_bytes(item["content"].encode("utf-8"))
    temporary.replace(destination)
    print("[INSTALLED]", name)
